INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(4771, 'koKR', 'Gambit Brzasku', 'Umieściłam Gambit Brzasku w pojemniku, który nam $gprzyniosłeś:przyniosłaś; – w tym, w którym były smocze jaja. Twoim zadaniem jest zanieść go w głąb Scholomancjum.$B$BNieumarły mag Vectus kieruje zespołem uczonych Plagi... umieść Gambit Brzasku w ich komnacie, zwanej „Salą Widokową”. Wejdzie on w reakcję z przebywającymi tam nieumarłymi i przy odrobinie szczęścia ich zniszczy!$B$BA potem pokonanie Vectusa nie powinno być problemem. Prawda?', 'Umieść Gambit Brzasku w Sali Widokowej Scholomancjum. Pokonaj Vectusa, a następnie wróć do Betiny Bigglezink.', 'Umieść Gambit Brzasku', 'Wróć do Betiny Bigglezink w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5149, 'koKR', 'Lalka Pameli', 'Ciocia Marlene kazała mi zostać tutaj, w naszym domu, bo tata musiał iść walczyć. Mój tata jest najdzielniejszym człowiekiem na całym świecie!$B$BAle jestem tu już bardzo długo, a on po mnie nie przyszedł. Czasem przychodzą źli ludzie i szepczą do mnie, a ja chcę, żeby tata ich przegonił, ale go tu nie ma!$B$BA czasem, kiedy robi się ciemno, chcę się pobawić lalką, ale nie mogę, bo zostawiłam ją w miasteczku.$B$BZnajdziesz dla mnie moją lalkę?', 'Znajdź lalkę Pameli.', '', '', '', '', '', '', 0),
(5168, 'koKR', 'Bohaterowie Włości Darrow', 'Bohaterowie Włości Darrow są bliscy memu sercu, a księga, którą mi $gprzyniosłeś:przyniosłaś;, Kroniki Włości Darrow, opowiada ich historie.$B$BOpowiada o paladynie Davilu Świetlistym Płomieniu i o tym, jak Krucjata zabrała jego libram do ratusza w Żagiewiu.$B$BJej karty mówią też o moim bracie, kapitanie Redpacie. Po jego zdradzie jego tarczę rozbito i porzucono, a teraz leży w najmniej spodziewanym miejscu – przy stodole na Plonach Gahrrona.$B$BZbierz te relikwie, $N. Otacza je bowiem przeznaczenie i tragedia.', 'Przynieś Libram Davila i Tarczę Redpatha Carlinowi Redpathowi.', '', 'Wróć do Carlina Redpatha w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5181, 'koKR', 'Złoczyńcy z Włości Darrow', 'Kroniki Włości Darrow opowiadają o złoczyńcach tamtej bitwy. Mówią, jak władca ghuli Horgus Pustoszyciel został w czasie bitwy zniszczony przez siły Przymierza. Jego ciało wrzucono do jeziora na północny zachód od Przeprawy Corina i jego czaszka wciąż tam leży.$B$BMarduka Czarnego nigdy nie pokonano, ale jego legendarny miecz strzaskano i zagubiono. Leży na dnie wąwozu na zachód od Przeprawy Corina.$B$BOdzyskaj te przedmioty, $N. Nie wiem czemu, ale jestem pewien, że ich los spoczywa w twoich rękach.', 'Przynieś Czaszkę Horgusa i Strzaskany miecz Marduka Carlinowi Redpathowi w Kaplicy Świetlistej Nadziei.', '', 'Wróć do Carlina Redpatha w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5206, 'koKR', 'Grabieżcy z Włości Darrow', 'Chronia powiedziała, że relikwie, które $gzebrałeś:zebrałaś;, są składnikami potężnego zaklęcia i potrzeba jeszcze jednego: czaszek sług Plagi, którzy brali udział w bitwie o Włości Darrow.$B$BWeź ten kryształ i poluj na czempionów Plagi dla ich czaszek. Kryształ jest zaczarowany; jeśli czempion brał udział w bitwie, to gdy przesuniesz kryształ nad jego czaszką, zacznie ona rezonować. Przynieś mi te rezonujące czaszki.$B$BIdź, $N. Czempionów Plagi znajdziesz na Trującej Polanie na północy i w Grzybiej Dolinie na zachodzie.', 'Przynieś 5 rezonujących czaszek i Mistyczny kryształ Carlinowi Redpathowi we Wschodnich Plagowiskach.', '', 'Wróć do Carlina Redpatha w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5211, 'koKR', 'Obrońcy Włości Darrow', 'Wielu obrońców poległo w bitwie o Włości Darrow. I wielu znów się błąka jako upiorne sługi Plagi! Odnajdź te biedne dusze i skróć ich cierpienia!$B$BPoluj na ghule kanibale, bredzące ghule i chorych obdzieraczy. Wiele z tych potworów było niegdyś dobrymi mieszkańcami Włości Darrow, a zniszczenie ich obecnych postaci wyzwoli ich dusze.$B$BZnajdziesz ich w Plagowym Lesie i przy Przeprawie Corina, a także w innych twierdzach Plagi we Wschodnich Plagowiskach.', 'Uwolnij 15 duchów z Włości Darrow i wróć do Carlina Redpatha.', '', 'Wróć do Carlina Redpatha w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', 'Uwolnione duchy z Włości Darrow', '', '', '', 0),
(5212, 'koKR', 'Ciało nie kłamie', 'Aptekarze Porzuconych nie są jedynymi istotami na tym świecie, które znają się na naukach.$B$BBadam zarazę od lat, $N. Wcześniej sądziliśmy, że siła zarazy słabnie, ale to, co odkryłam tutaj, na Plagowiskach, jest zdumiewające. Zaraza zdaje się przybierać na sile!$B$BMuszę przeprowadzić więcej badań! Najsilniejszym źródłem zarazy jest skażone ciało świeżo zarażonych. Udaj się do Stratholmu i przynieś mi próbki, $N.$B', 'Zdobądź 10 próbek zarażonego ciała w Stratholmie i zanieś je Betinie Bigglezink. Podejrzewasz, że każda istota w Stratholmie może mieć przy sobie taką próbkę.', '', 'Wróć do Betiny Bigglezink w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5213, 'koKR', 'Czynnik aktywny', 'Musisz zapuścić się głębiej w Stratholm, $N.$B$BZa pierwszymi bramami znajdziesz zigguraty. Wiemy, że Plaga czerpie z tych budowli wielką moc. Przeszukaj zigguraty i wróć z wszelkimi informacjami, jakie zdołasz odkryć.$B', 'Udaj się do Stratholmu i przeszukaj zigguraty. Znajdź nowe Dane Plagi i zanieś je Betinie Bigglezink.$B', '', 'Wróć do Betiny Bigglezink w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5214, 'koKR', 'Wielki Fras Siabi', 'Straszna rzecz... to, co spotkało Frasa. Widzisz, miasto zostało złupione, a Fras nie chciał zostawić swojego cennego towaru. Ostatnie, co pamiętam, to jak mówił: „Spalę każdy listek, zanim położą na nich te swoje przeklęte, brudne łapska!”$B$BMoże i lubię dobre cygaro, ale głupi nie jestem. Tego dnia zostawiłem Frasa i jego uroczy sklepik. Zakładam, że spłonął razem z nim, ale jeśli jest choć cień szansy, że przetrwało choćby jedno pudełko jego słynnego tytoniu...$B$BCo ty na to, $N? Znajdziesz pudełko dla starego Smokeya?', 'Znajdź sklep tytoniowy Frasa Siabiego w Stratholmie i odzyskaj pudełko Przedniego tytoniu Siabiego. Gdy skończysz, wróć do Smokeya LaRue.$B', '', 'Wróć do Smokeya LaRue w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5241, 'koKR', 'Wujek Carlin', 'Czasem w nocy słyszę, jak płacze mój wujek Carlin. Brzmi to tak, jakby był daleko, na wschodzie.$B$BMam nadzieję, że nie płacze przeze mnie! $N, znajdziesz mojego wujka i powiesz mu, że nic mi nie jest?$B$BJak go znajdziesz, powiedz mu, że na niego czekam i chcę usłyszeć historię, którą mi kiedyś opowiadał... tę o królikach i dżemie z jagód! Ta historia jest taka śmieszna!', 'Znajdź Carlina Redpatha.', '', '', '', '', '', '', 0),
(5243, 'koKR', 'Domy Świętego', 'Moje nieżycie traktuję jak chorobę, $N. Dolegliwość, która wymaga jedynie leczenia; jest jednak także wielkim błogosławieństwem dla Argentowego Brzasku. Czyż jest lepsze narzędzie do karania pogan z Plagi niż sami nieumarli?$B$BKoledzy czczą mnie z powodu ofiar, które poniosłem, ale te wyróżnienia nic dla mnie nie znaczą.$B$BJeśli chcesz pomóc Argentowemu Brzaskowi, mam dla ciebie zadanie.$B$BUdaj się do Stratholmu i odzyskaj nasz zapas wody święconej. Przeszukaj skrzynie z zaopatrzeniem.$B', 'Udaj się do Stratholmu na północy. Przeszukaj skrzynie z zaopatrzeniem porozrzucane po mieście i odzyskaj 5 porcji Wody święconej ze Stratholmu. Gdy zbierzesz dość tego błogosławionego płynu, wróć do Leonida Barthalomew Czcigodnego.', '', 'Wróć do Leonida Barthalomew Czcigodnego w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5245, 'koKR', 'Udręczone duchy Kel\'Theril', 'Duchy Wysoko Urodzonych to nieszczęsne istoty, bez dwóch zdań. Wciąż szukają kawałków tego, co przeklęło je i uwięziło w Kel\'Theril na zawsze – skradzionej relikwii.$B$BJeśli tak cię to ciekawi, weź mój kilof i idź na południe nad jezioro. Zobacz, czy zdołasz wydobyć jej kawałki spod lodu.$B$BNie powiem ci nic o tym, co znajdziesz, ale znam kogoś, kto może coś wiedzieć... Aurora Niebowołaczka; mieszka w pobliżu Wieży Północnej Przełęczy, w północnej części Wschodnich Plagowisk.', 'Użyj Kilofa Jarona, by odnaleźć cztery fragmenty relikwii Wysoko Urodzonych. Zanieś je Aurorze Niebowołaczce we Wschodnich Plagowiskach.', '', 'Wróć do Aurory Niebowołaczki we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5246, 'koKR', 'Fragmenty przeszłości', 'Nie zdawałam sobie sprawy... Wybacz moje nieczułe słowa, $N.$B$BNie chcę rozpamiętywać błędów moich przodków, ale jeśli twoja prośba jest naprawdę szczera, pomogę ci.$B$B<Aurora ogląda fragmenty.>$B$BSądzę, że to Kryształ Zin-Malor – artefakt, który potrafi pomieścić i okiełznać potężne siły tajemnej mocy. Mógł służyć dobru, lecz złe zamiary tych, którzy go skradli, sprawiły, że pękł.$B$BUdaj się do Świątyni Zin-Malor w Aszarze – mogę tylko mieć nadzieję, że księga wciąż tam jest.', 'Znajdź Święte pisma Wysoko Urodzonych w Świątyni Zin-Malor w Aszarze i zanieś je Aurorze Niebowołaczce w pobliżu Wieży Północnej Przełęczy we Wschodnich Plagowiskach.', '', 'Wróć do Aurory Niebowołaczki we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5247, 'koKR', 'Fragmenty przeszłości', 'Zdołam ci pomóc, jeśli naprawdę chcesz odtworzyć ten artefakt.$B$BAby na powrót scalić kawałki, będę potrzebować przedmiotów o silnych właściwościach magicznych. Sztabki zaklętego torium i pięciu porcji Kryształowego odnowienia... Musisz też zaczerpnąć wody z miejsca, które może się wydać dość nieoczekiwane... Znajdź złowrogi staw w Alei Eldreth w Srogomłotach w Feralas i napełnij tę fiolkę.$B$BPod twoją nieobecność spróbuję wyczytać z tych stron wiedzę potrzebną do naprawienia szkód wyrządzonych relikwii.', 'Przynieś Sztabkę zaklętego torium, 5 porcji Kryształowego odnowienia i Fiolkę złowrogiej wody Aurorze Niebowołaczce w pobliżu Wieży Północnej Przełęczy we Wschodnich Plagowiskach.', '', 'Wróć do Aurory Niebowołaczki we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5248, 'koKR', 'Udręczeni przeszłością', '$N, opłakuję to, co wydarzyło się w przeszłości. Tak jak ten kryształ, elfy jako rasa zostały rozbite. Nie wiem, czy te kawałki kiedykolwiek znów połączą się w jedno, ale mój smutek złagodziła możliwość pomocy ci w tym jednym drobnym zadaniu.$B$BNie wolno nam zapominać o przeszłości, $N...$B$BProszę, zanieś Kryształ Zin-Malor z powrotem nad Jezioro Kel\'Theril. Musisz odnaleźć ducha Wysoko Urodzonego, który pojmuje błąd popełniony tak dawno temu. Pokaż duchowi, że znów wszystko naprawiliśmy.', 'Zanieś Kryształ Zin-Malor nad Jezioro Kel\'Theril w Zimozdroju i odnajdź ducha Wysoko Urodzonego, który zechce z tobą porozmawiać.', '', '', '', '', '', '', 0),
(5251, 'koKR', 'Archiwista', 'Wszystko, co doprowadzone do skrajności, jest groźne dla naszego świata, $N. Weźmy na przykład Szkarłatną Krucjatę. Czy sądzisz, że jej ślepy fanatyzm służy wyższemu dobru? Ilu niewinnych zgładzili w imię Światłości?$B$BBluźniercy, co do jednego!$B$BJeden z nich szczególnie mnie jednak interesuje: archiwista Galford ze Stratholmu. Człowiek, który strzeże najcenniejszych dokumentów Krucjaty. Zgładź go i spal jego archiwa! Jeśli ci się uda, wróć do mnie po nagrodę.', 'Udaj się do Stratholmu i odnajdź archiwistę Galforda ze Szkarłatnej Krucjaty. Zgładź go i spal Szkarłatne Archiwum.', '', 'Wróć do księcia Nicholasa Zverenhoffa w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', 'Archiwum spalone', '', '', 0),
(5262, 'koKR', 'Prawda wychodzi na jaw', 'Gdy kurz opada w komnacie, próbujesz zebrać myśli. Rozważasz wydarzenia, które właśnie miały miejsce, i wciąż nie możesz pojąć wagi sytuacji.$B$BWielki Krzyżowiec Szkarłatnej Krucjaty demonem? I to nie byle jakim demonem, ale bratem Varimathrasa, arcylorda Podmiasta?$B$BOstrożnie chowasz odciętą głowę upiornego władcy do plecaka. Z pewnością nikt nie uwierzy w twoją opowieść bez dowodu.$B$BTrzeba natychmiast powiadomić księcia Nicholasa Zverenhoffa!', 'Zanieś Głowę Balnazzara księciu Nicholasowi Zverenhoffowi we Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5263, 'koKR', 'Ponad wszelką miarę', 'Wykazujesz wrodzony talent do niszczenia i wykonujesz rozkazy. Rzadko spotyka się te dwie cechy naraz. Zaczynam sądzić, że możesz się stać znakomitym narzędziem boskiej sprawiedliwości.$B$B<Zverenhoff składa dłonie przed twarzą.>$B$BChłopiec na posyłki Kel\'Thuzada rządzi Stratholmem. Udowodnij mi, że jesteś $gczempionem:czempionką; – moim $gczempionem:czempionką;. Zgładź barona Zerwikrusza i wróć do mnie z jego głową.$B', 'Wyrusz do Stratholmu i zgładź barona Zerwikrusza. Weź jego głowę i wróć do księcia Nicholasa Zverenhoffa.$B', '', 'Wróć do księcia Nicholasa Zverenhoffa w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5264, 'koKR', 'Lord Maxwell Tyrosus', 'Za chwilę dostąpisz wielkiego zaszczytu, $N.$B$BLord Maxwell pragnie cię nagrodzić za twoją służbę Argentowemu Brzaskowi!$B$BOd lat Maxwell nie udzielał audiencji obcym.$B', 'Porozmawiaj z lordem Maxwellem Tyrosusem. Jest w kościele.', '', '', '', '', '', '', 0),
(5265, 'koKR', 'Warownia Argentu', 'Przez lata Warownia Argentu pozostawała zamknięta. Nikt nie był godzien sięgnąć do jej wnętrza i zaczerpnąć z niej mocy Argentowego Brzasku – aż do dziś.$B$BWarownia Argentu stoi przed tobą otworem, $N.', 'Otwórz Warownię Argentu i odbierz swoją nagrodę.', '', '', '', '', '', '', 0),
(5281, 'koKR', 'Niespokojne dusze', 'Są tacy, którzy zginęli tragicznie podczas upadku Stratholmu. Wielu odebrało sobie życie, woląc rzucić się w niezliczone płomienie tlącego się miasta, niż stać się częścią Plagi.$B$BTeraz przemierzają ulice Stratholmu jako niespokojne duchy.$B$BMusimy im pomóc, $N!$B$BMam współpracownika imieniem Egan, który dokonuje cudów z duchami i duszami. Odszukaj go. Wędruje po wschodnich Plagowiskach w pobliżu Stratholmu i testuje swoje wynalazki.', 'Znajdź Egana. Wiesz tylko, że ostatnio widziano go w okolicach Stratholmu.', '', '', '', '', '', '', 0),
(5282, 'koKR', 'Niespokojne dusze', 'Moc – wolę dalszego życia i oddychania – czerpię z bezbrzeżnej nienawiści do Plagi i wszystkiego, czego dokonała. Nie jestem jednak fanatykiem. Są tacy, jak Szkarłatna Krucjata, którzy prędzej zniszczą niewinnych nieumarłych, niż okażą im choć odrobinę współczucia.$B$BI tu dochodzę do rzeczy: moja spluwa. Uwolni udręczone dusze ze Stratholmu.$B$BUżyj jej na duchach nawiedzających splądrowane ulice. Uwolnij ich dusze.', 'Użyj Spluwy Egana na upiornych i widmowych mieszkańcach Stratholmu. Gdy niespokojne dusze wyrwą się ze swych upiornych powłok, użyj spluwy ponownie – a odzyskają wolność!$B$BUwolnij 15 niespokojnych dusz i wróć do Egana.', '', 'Wróć do Egana w Plagowym Lesie we Wschodnich Plagowiskach.', 'Uwolnione dusze', '', '', '', 0),
(5463, 'koKR', 'Dar Menethila', 'Patrzyłem, jak człowiek, Rez Szept Mrozu, oddał swą nieśmiertelną duszę Królowi Liszowi. Przyłożył sobie sztylet do gardła i z uśmiechem poderżnął je od ucha do ucha. Jego ciało osunęło się w obrębie pentagramu. Król Lisz stanął nad poległym magiem i jednym ruchem powołał do istnienia Reza Szept Mrozu – lisza.$B$B<Leonid wpatruje się w ziemię, a potem podnosi na ciebie wzrok.>$B$BTak, $N, pamiętam. To, czego szukasz, ma nazwę – Dar Menethila: ziemia pobłogosławiona przez Króla Lisza, dla Plagi uświęcona.$B', 'Udaj się do Stratholmu i odnajdź Dar Menethila. Połóż Pamiątkę wspomnień na tej nieświętej ziemi.', '', '', '', '', '', '', 0),
(5464, 'koKR', 'Dar Menethila', 'Dusza poległego lgnie do tego, co symbolizuje jej dawne życie, i przemienia przedmiot w pamiątkę związaną z duszą. Podnosisz przedmiot i chowasz go do plecaka.', 'Zanieś Pamiątkę związaną z duszą Leonidowi Barthalomew we Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5508, 'koKR', '', '', '', '', 'Wróć do księcia Nicholasa Zverenhoffa we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5509, 'koKR', '', '', '', '', 'Wróć do księcia Nicholasa Zverenhoffa we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5510, 'koKR', '', '', '', '', 'Wróć do księcia Nicholasa Zverenhoffa we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5513, 'koKR', '', '', 'Przynieś 10 Żetonów męstwa Argentowego Brzasku kwatermistrzyni Breechlock w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', 'Wróć do kwatermistrzyni Mirandy Breechlock w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5517, 'koKR', '', '', 'Przynieś 25 Żetonów męstwa Argentowego Brzasku kwatermistrzyni Breechlock w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', 'Wróć do kwatermistrzyni Mirandy Breechlock w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5529, 'koKR', 'Zarażone pisklęta', 'Argentowy Brzask dowiedział się niedawno, że Plaga tworzy własne, zarażone smocze stado! Musimy ją powstrzymać – jeśli Plaga zdobędzie armię smoków, przetoczy się przez Azeroth bez przeszkód!$B$BJej nekromanci hodują zarażone smoki w Scholomancjum, pośrodku Jeziora Darrowmere.$B$BUdaj się do Scholomancjum i zabij tyle piskląt, ile zdołasz... zanim urosną!', 'Zabij 20 zarażonych piskląt, a następnie wróć do Betiny Bigglezink w Kaplicy Świetlistej Nadziei.', '', 'Wróć do Betiny Bigglezink w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5530, 'koKR', '', '', '', '', 'Wróć do kwatermistrzyni Mirandy Breechlock we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5531, 'koKR', 'Betina Bigglezink', 'Jaja, które $gprzyniosłeś:przyniosłaś;, miały posłużyć Pladze w eksperymentach nad stworzeniem zarażonego smoczego stada. Te zamrożone jaja czarnych smoków byłyby bezcenne dla ich badań i z pewnością przyspieszyłyby ich plany.$B$BCzas położyć kres tym badaniom.$B$BZanieś zamrożone jaja Betinie Bigglezink, która czeka na zewnątrz. Zna się dobrze na nauce i alchemii i stworzyła broń, której możemy użyć przeciw Pladze. Z twoją pomocą zadamy im ciężki cios.', 'Zanieś Zamrożone jaja Betinie Bigglezink.', '', '', '', '', '', '', 0),
(5532, 'koKR', '', '', '', '', 'Wróć do kwatermistrzyni Mirandy Breechlock we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5542, 'koKR', 'Diabelskie psy', 'Jeśli zamierzasz tu zostać, proszę tylko, żebyś $gzapracował:zapracowała; na swoje utrzymanie. Mamy tu wiele utrapień, którym przydałoby się trochę „dyscypliny”.$B$BMożesz zacząć od plagowych ogarów i ich chuder.$B$BNie mogę zaoferować wiele w zamian, ale jeśli ci się uda, możesz liczyć na ciepły posiłek i rozmowę.', 'Zabij 20 chuder plagowego ogara, 5 plagowych ogarów i 5 rozszalałych plagowych ogarów. Po wykonaniu zadania wróć do Tiriona Fordringa.', '', 'Wróć do Tiriona Fordringa nad Rzeką Thondroril we Wschodnich Plagowiskach.', '', '', '', '', 0),
(5543, 'koKR', 'Niebo zabarwione krwią', 'Biada tym, którzy w głupocie zapuszczają się na Plagowiska. W tych lasach gnieździ się wszelkie plugastwo – od fanatycznej Szkarłatnej Krucjaty, która zabije każdego, kto nie nosi znaku Krucjaty, po morderczą Plagę, która chce tylko zasilić swoje szeregi kolejnymi nieumarłymi.$B$BNawet dzikie zwierzęta przemieniły się w drapieżne bestie pożerające ludzi. Proszę cię, zniszcz te, które atakują z powietrza: plagowe nietoperze.', 'Zabij 30 plagowych nietoperzy i wróć do Tiriona Fordringa.', '', 'Wróć do Tiriona Fordringa w Zachodnich Plagowiskach.', '', '', '', '', 0),
(5544, 'koKR', 'Czerwiowe żarcie', 'Kończą mi się zapasy jedzenia, $N. Wstyd mi przyznać, ale może mi nie starczyć, by się z tobą podzielić.$B$BCzy pomożesz staremu człowiekowi w prostym zadaniu? W tej okolicy jedynymi zwierzętami, których nie dotknęło spustoszenie zarazy, są padlinożerne czerwie. Choć ich mięso jest raczej mdłe w smaku, łatwo je zakonserwować na wiele miesięcy. Potrzebuję kilkuset funtów, by uzupełnić zapasy na nadchodzącą zimę!', 'Odszukaj w okolicy padlinożerne czerwie i padlinożernych pożeraczy. Zabijaj je i zbieraj ich mięso. Gdy zbierzesz 15 płatów mięsa padlinożernego czerwia, wróć do Tiriona Fordringa.$B', '', 'Wróć do Tiriona Fordringa w Zachodnich Plagowiskach.', '', '', '', '', 0),
(5582, 'koKR', 'Zdrowa smocza łuska', 'To łuska zrzucona przez zarażone smocze pisklę. Ale w przeciwieństwie do innych, dziobatych i sączących się łusek młodego stworzenia, ta rzadka łuska jest zdrowa i nieskazitelna.$B$BBetina Bigglezink zechce zbadać taką próbkę.', 'Zanieś Zdrową smoczą łuskę Betinie Bigglezink w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5601, 'koKR', 'Siostrzyczka Pamela', 'Uciekłam z Lordaeronu podczas wielkiej wojny i miałam szczęście, że zdążyłam, zanim Plaga przetoczyła się przez moją ojczyznę i zamieniła ją w zarażony koszmar! Ja miałam szczęście, ale moja rodzina nie. Obawiam się, że wszyscy zginęli w bitwie o Włości Darrow.$B$BWłości Darrow to wioska we Wschodnich Królestwach, położona wśród południowych wzgórz dzisiejszych Wschodnich Plagowisk. Pojedziesz tam i poszukasz mojej rodziny? Tak bardzo za nimi tęsknię, zwłaszcza za moją młodszą siostrzyczką Pamelą.$B$BProszę, odnajdź ją dla mnie!', '', '', '', '', '', '', '', 0),
(5742, 'koKR', '', 'Ciężko $gpracowałeś:pracowałaś;, $gprzyjacielu:przyjaciółko;. Daj odpocząć zmęczonym kościom i pozwól, że należycie się przedstawię.$B', 'Wysłuchaj, co ma do powiedzenia Tirion Fordring.', 'Opowieść Tiriona', '', '', '', '', '', 0),
(5781, 'koKR', 'O zapomnianych wspomnieniach', 'Aby pomóc Taelanowi odzyskać to, co utracił, musisz zebrać przedmioty z jego przeszłości.$B$BPierwszy z nich to zabawka, którą dałem mu na siódme urodziny. Była jego najcenniejszym skarbem: miniaturowy młot bojowy, dokładna kopia mojego własnego.$B$BGdy wygnano mnie za zdradę, matka powiedziała mu, że nie żyję. Zabrano go do mojego fałszywego grobu w Podziemiach, gdzie pogrzebał młot wraz z pamięcią o mnie – na zawsze.$B$BMusisz udać się do Podziemi i odzyskać młot Taelana.', 'Udaj się do Podziemi – w najbardziej wysuniętej na południe części Wschodnich Plagowisk – i odzyskaj Młot Taelana. Po wykonaniu zadania wróć do Tiriona Fordringa.', '', '', '', '', '', '', 0),
(5845, 'koKR', 'O utraconym honorze', 'Zakon Srebrnej Dłoni został doszczętnie wybity, gdy zginął Uther.$B$BChłopak wytrwał, jak długo mógł. Zepchnięty do zniszczonej wojną osady w Północnej Dolinie, stoczył tam swój ostatni bój.$B$BCzy ktokolwiek z Zakonu pozostał przy życiu, zastanawiał się – i czy miało to jeszcze znaczenie?$B$BZ tą myślą Taelan rzucił sztandar Zakonu i wyrzekł się wszystkiego, co znał. Jego honor pozostał na przesiąkniętej krwią ziemi Północnej Doliny.$B$BMusisz udać się do Północnej Doliny i odzyskać ten symbol utraconego honoru.', 'Udaj się do Północnej Doliny w północno-wschodniej części Wschodnich Plagowisk i odzyskaj Symbol utraconego honoru. Po wykonaniu zadania wróć do Tiriona Fordringa.', '', '', '', '', '', '', 0),
(5942, 'koKR', 'Ukryte skarby', 'Tatuś kazał mi dać ci ten klucz. Powiedział, że otwiera skrzynię z tyłu, za domem.$B$BChciał też, żebym ci podziękowała. $GZrobiłeś:Zrobiłaś; mu przysługę? $GPowiedziałeś:Powiedziałaś; mu, że $gznalazłeś:znalazłaś; moją lalkę?$B$BNo to masz klucz. I dziękuję ci, $N. Dziękuję! Jesteś $gbardzo miłym panem:bardzo miłą panią;!', 'Zanieś Klucz Josepha do Skrzyni Josepha.', '', '', '', '', '', '', 0),
(6021, 'koKR', 'Zaeldarr Wygnaniec', 'Uwierzysz? Po tych wszystkich kłopotach, jakie mamy na Plagowiskach... musimy się jeszcze martwić złodziejami. I to nie zwykłymi złodziejami, tylko trollami złodziejami.$B$BI to nie zwykłymi trollami złodziejami. Martwymi trollami złodziejami!$B$BPrzewodzi im taki wielki, martwy troll, Zaeldarr Wygnaniec. Przychodzą tu nocą, kradną ciała z dołu poniżej i zabierają je do swojej plugawej kryjówki martwych trolli – do Podziemi na zachodzie.$B$BIdź tam i rozpraw się z Zaeldarrem, $N. Mam już po dziurki w nosie jego wybryków!', 'Przynieś Głowę Zaeldarra dozorcy Alenowi w Kaplicy Świetlistej Nadziei.', '', 'Wróć do dozorcy Alena w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(6022, 'koKR', 'Zabijać z rozmysłem', 'Dopóki przebywasz w moim gospodarstwie, zabijasz z rozmysłem.$B$BTwoim pierwszym zadaniem będzie nakarmienie moich ogarów.$B$BWeź ten moździerz z tłuczkiem i udaj się do Przeprawy Corina. Znajdziesz tam bogaty wybór sług Plagi do wyrżnięcia. Z ich świeżych ścierw potrzebuję żywej zgnilizny. Weź tę żywą zgniliznę, utłucz ją w moździerzu i odstaw, by skrzepła. Przynieś tu skrzepłą zgniliznę.$B$BI zrozum, imbecylu, że żywa zgnilizna z nieumarłych nie pozostaje „żywa” zbyt długo. Musisz zabijać szybko!', 'Udaj się do Przeprawy Corina na wschodzie i wyrżnij sługi Plagi, które zamieszkują miasteczko. Zbierz 7 porcji Żywej zgnilizny w mniej niż 10 minut. Użyj Moździerza z tłuczkiem, by utłuc Żywą zgniliznę na Skrzepłą zgniliznę.', '', '', '', '', '', '', 0),
(6024, 'koKR', 'Błaganie Hamei', 'Zabij mnie. Zanim będzie za późno.$B$BJestem Hameya. W drodze do Zul\'Mashar ja i moi bracia zjedliśmy zepsute mięso... i przemieniliśmy się. Jesteśmy zarażeni.$B$BSłyszę teraz słowa lisza, które każą mi dotrzeć do Zul\'Mashar i zarazić więcej moich pobratymców. Nie potrafię się im oprzeć, dlatego napisałem ten zwój, zanim opuściła mnie wola.$B$BZakopałem skrzynię w ziemi obok wozu za tą kryptą, ale otworzy ją tylko mój klucz. Mam go przy sobie. Jeśli chcesz mojego skarbu, znajdź mnie.$B$BZabij mnie. Zanim będzie za późno.', 'Zabij infiltratora Hameyę. Użyj jego klucza na Kopczyku ziemi za Podziemiami.', '', 'Wróć do Kopczyka ziemi we Wschodnich Plagowiskach.', '', '', '', '', 0),
(6026, 'koKR', 'Sporo wymagasz', 'Ci tutaj ludzie z Argentowego Brzasku zlecili staremu Smokeyowi małą robótkę rozbiórkową. Mamusia Smokeya nie wychowała głupka. Jak złoto ląduje na stole, Smokey jest do usług. Takie mam motto!$B$BChętnie podzielę się z tobą zapłatą, jeśli się trochę nabiegasz. Umowa jest taka: ja pójdę do Plagowego Lasu i oznaczę budynki, które trzeba wysadzić. Ty zbierzesz składniki na bomby. Spotkamy się tu, gdy wszystko będziesz mieć. Umowa stoi?', 'Smokey LaRue chce, żebyś $gzdobył:zdobyła; 2 Sztabki torium, 1 Złoty pręt, 8 Bomb burzących i 8 Niestabilnych spustów.$B$BPo te przedmioty musisz się udać do kowala i inżyniera.', '', 'Wróć do Smokeya LaRue w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(6030, 'koKR', 'Książę Nicholas Zverenhoff', 'Pewne medium – odludek z tych stron, niejaki Umbranse – dostarczyło Argentowemu Brzaskowi niezłe arcydzieło literackie... które jest chyba największym zbiorem bełkotu, jaki kiedykolwiek widziałem na piśmie.$B$BJeden z najbardziej szanowanych przywódców Brzasku, książę Nicholas Zverenhoff, to wybitny lingwista. Zaniesiesz mu to ode mnie – oczywiście za nagrodą? Znajdziesz go w Kaplicy Świetlistej Nadziei, daleko we wschodniej części Wschodnich Plagowisk.', 'Dostarcz księgę „Studia nad mową duchów” księciu Nicholasowi Zverenhoffowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(6041, 'koKR', 'Gdy Smokey śpiewa, robi się gorąco', 'Kiedy ty $gzbierałeś:zbierałaś; zaopatrzenie, kilku moich ludzi oznaczyło budynki Plagi, które trzeba wyburzyć.$B$BPlan jest taki: dam ci dziesięć lasek mojej specjalnej mieszanki. Zaniesiesz je do Plagowego Lasu i podłożysz w budowlach Plagi, które kazałem oznaczyć do detonacji.$B$B<Smokey pstryka palcami.>$B$BBum! To takie proste.', 'Udaj się do Plagowego Lasu na północny zachód od Kaplicy Świetlistej Nadziei. Zniszcz 8 budowli Plagi, używając Specjalnej mieszanki Smokeya przy Znaku detonacji umieszczonym w każdym budynku. Smokey kazał oznaczyć zigguraty i rzeźnie.$B$BGdy podłożysz bombę, wyjdź z budynku i podziwiaj swoje dzieło.$B$BA tak przy okazji, Specjalna mieszanka Smokeya jest dość... niestabilna.', '', 'Wróć do Smokeya LaRue w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', 'Zniszczone budowle Plagi', '', '', '', 0),
(6042, 'koKR', 'Drobne utrapienia nieżycia', 'Nie da się zrobić dwóch kroków poza tę farmę, żeby nie wpaść na któregoś z tych wstrętnych nietoperzy. Chcę móc wyprowadzić ogary i rżnąć Plagę, nie będąc nękanym przez przeklęte, brudne nietoperze. Rzecz jasna, mam lepsze rzeczy do roboty niż bezmyślne zabijanie nietoperzy dzień w dzień. Ty natomiast nie masz.$B$BCo? Twój trening? To jest twój trening! A teraz zejdź mi z oczu i nie wracaj, dopóki nie zabijesz sporej liczby tych skrzydlatych demonów. Nie rozczaruj mnie.', 'Zabij 20 trujących plagowych nietoperzy i 10 potwornych plagowych nietoperzy. Gdy skończysz, wróć do Nathanosa Herolda Plagi.', '', '', '', '', '', '', 0),
(6133, 'koKR', 'Polecenie lorda tropicieli', 'Wysokie elfy ze Stróżówki Quel\'Lithien mają coś, co należy do mnie, $N: dokument opisujący moje życie jako śmiertelnika.$B$BZanim zapytasz: nie, z całą pewnością nie masz prawa do takich informacji. Po prostu rób, co ci każę, robaku: odzyskaj rejestr.$B$BI, imbecylu, postaraj się zostawić za sobą jak najwięcej zamętu i żalu. Niech cierpią...', 'Udaj się na północne rubieże Wschodnich Plagowisk i odzyskaj Rejestr Quel\'Thalas. Przedmiot znajduje się gdzieś w Stróżówce Quel\'Lithien.$B$BMusisz też zabić 8 tropicieli, 8 wędrowców szlaków i 8 leśników.', '', '', '', '', '', '', 0),
(6135, 'koKR', 'Zmierzchoskrzydły, och, jak ja cię nienawidzę...', 'Jak dotąd $gwykonywałeś:wykonywałaś; misje, które ci zlecałem, choć nie zawsze w najlepszym tempie.$B$BPrzypuszczam, że uważasz się za $ggotowego:gotową; na wyzwanie. Tak... Tak, imbecylu, może jesteś $ggotów:gotowa; na bardziej wymagające misje.$B$BAlbinotyczny demoniczny nietoperz, Zmierzchoskrzydły, krąży po okolicy na północ stąd. Wytrop go i zgładź. Wróć do mnie z kępką jego białego futra, a zostaniesz $gnagrodzony:nagrodzona;.$B', 'Znajdź Zmierzchoskrzydłego i zabij go. Zdobądź z jego zwłok Kępkę futra Zmierzchoskrzydłego i zanieś ją Nathanosowi Heroldowi Plagi.$B$BPodobno Zmierzchoskrzydły krąży po okolicy na północ od Zagrody Marrisów.', '', '', '', '', '', '', 0),
(6136, 'koKR', 'Ten korpulentny', 'Za obozowiskiem Argentowego Brzasku w Kaplicy Świetlistej Nadziei, na zachód od Północnej Doliny, znajdziesz korpulentną bestię-czerwia, Borelgore\'a.$B$BStraciłem przez tego potwora całe regimenty. Jego rozmiary nie znają granic! Im więcej zje, tym bardziej tyje...$B$BChoć nie ucierpiałbym emocjonalnie, gdyby bestia cię pożarła, wolałbym, żebyś to ty $gzwyciężył:zwyciężyła;. Borelgore nieraz pożerał tych, którzy próbowali na niego polować.', 'Znajdź Borelgore\'a na północnych pustkowiach Wschodnich Plagowisk i zgładź go. Po wykonaniu misji wróć do Nathanosa Herolda Plagi.', '', 'Wróć do Nathanosa Herolda Plagi w Zagrodzie Marrisów we Wschodnich Plagowiskach.', '', '', '', '', 0),
(6146, 'koKR', 'Podstęp Nathanosa', 'Wprowadziłem w tym rozkazie pewne poprawki. Jeśli nasz mały podstęp się powiedzie, odsłonią Szkarłatną wyrocznię, a wtedy uderzymy!$B$BA teraz uważaj, $N. Masz dostarczyć ten rozkaz lordowi krzyżowcowi Valdelmarowi.$B$BJak? Wręczysz mu go, imbecylu.$B$BZanieś rozkaz i to zgniłe jabłko do Dłoni Tyra. Gdy wejdziesz do miasta, zjedz jabłko. Przemienisz się w coś bardziej... strawnego dla ludzi. Weź rozkaz i wręcz go lordowi krzyżowcowi Valdelmarowi.', 'Udaj się do Dłoni Tyra na południowy wschód od Zagrody Marrisów. Na miejscu ugryź Zgniłe jabłko. W przebraniu członka Szkarłatnej Krucjaty dostarcz Rozkaz Wielkiego Krzyżowca lordowi krzyżowcowi Valdelmarowi.', '', 'Wróć do lorda krzyżowca Valdelmara w Ruinach Szkarłatnej Enklawy we Wschodnich Plagowiskach.', '', '', '', '', 0),
(6147, 'koKR', 'Powrót do Nathanosa', 'Wielki Krzyżowiec ma nietypowe życzenie. Hmm, mniejsza z tym... jego wola zostanie spełniona. Wróć do Szkarłatnego Bastionu i powiadom go, że Wyrocznia wkrótce wyruszy w drogę.$B$BPodejmiemy wszelkie środki ostrożności, by bez szwanku dotarła do Stratholmu.', 'Wróć z nowymi informacjami do Nathanosa Herolda Plagi.$B', '', '', '', '', '', '', 0),
(6148, 'koKR', 'Szkarłatna wyrocznia Demetria', 'Demetria jest główną doradczynią Wielkiego Krzyżowca. Nazywają ją Wyrocznią z powodu jej „nadprzyrodzonych” zmysłów. Pomogła Krucjacie odnieść kilka zwycięstw nad Plagą.$B$BChoć nasz podstęp zdołał ją odsłonić, jeśli naprawdę ma zdolności parapsychiczne, bez wątpienia spodziewa się jakichś kłopotów. Ty będziesz tymi „kłopotami”.$B$BWytrop Wyrocznię i zlikwiduj ją. W tej chwili powinni właśnie wyruszać z Dłoni Tyra. Przynieś mi chlubę, robaku.$B', 'Szkarłatna Krucjata jest w drodze. Gdzieś na trakcie z Dłoni Tyra do Stratholmu znajdziesz Wyrocznię Demetrię i jej świtę. Wytrop ją i zabij. Jeśli ci się uda, wróć do Nathanosa Herolda Plagi.', '', '', '', '', '', '', 0),
(6163, 'koKR', 'Ramstein', 'Zostałem przytłoczony. Właśnie w tym gospodarstwie stałem... i broniłem swojej pozycji w obronie Lordaeronu. Farmę i wszystko, co na niej było, zalała gigantyczna fala Plagi.$B$BTa kreatura. To plugastwo. Unosiło się nade mną, a z jego rozwartej klatki piersiowej zwisały wnętrzności.$B$BObudziłem się jako sługa Plagi. Przez tak długi czas byłem bezradny. Mój umysł zlał się z umysłem Króla Lisza.$B$BOna po mnie przyszła... gdzieś w głębi, jakoś wiedziałem, że przyjdzie. Wolność.$B$BA teraz muszę się zemścić – zemścić na tym, co odebrało mi życie. Zniszcz to.', 'Udaj się do Stratholmu i zabij Ramsteina Żarłoka. Weź jego głowę jako pamiątkę dla Nathanosa.', '', '', '', '', '', '', 0),
(6164, 'koKR', 'Księga pokwitowań Augustusa', 'Jestem gotów do interesów! Czego sobie życzysz?$B$BO, chwila... nie mogę otworzyć sklepu bez mojej księgi pokwitowań. Jak mam wszystkiego pilnować bez mojej księgi pokwitowań?$B$BMusiałem ją zostawić gdzieś w miasteczku. Miałem pokój w gospodzie... księga musi tam być.$B$BPrzynieś mi moją księgę. Proszę, przynieś mi ją! Przynieś mi księgę, a zobaczysz! Otworzę sklep i przekonasz się, że moje ceny są SZALONE!', 'Zdobądź Księgę pokwitowań Augustusa z gospody w Dolinie Grozy.', '', 'Wróć do Augustusa Dotkniętego w Dolinie Grozy we Wschodnich Plagowiskach.', '', '', '', '', 0),
(7621, 'koKR', 'Ostrzeżenie', '', '', '', '', '', '', '', '', 0),
(7622, 'koKR', 'Równowaga Światła i Cienia', 'Musisz dokonać tego, czego ja nie zdołałam: ocalić wieśniaków, których wyrżnięto, gdy uciekali ze Stratholmu.$B$BBędą iść w stronę światła, a ty musisz zapewnić im przetrwanie. Jeśli zbyt wielu zginie, nasze przeklęte istnienie będzie trwać dalej – poniesiesz porażkę.$B$BSprawdzona zostanie każda umiejętność, modlitwa i zaklęcie, jakie $gpoznałeś:poznałaś;. Niech Światłość cię chroni, $N.', 'Ocal 50 wieśniaków, zanim zginie 15. Jeśli ci się uda, porozmawiaj z Eris Płomień Przystani.$B$BNa Słupie Śmierci możesz sprawdzić, ilu wieśniaków zginęło.', 'Równowaga Światła i Cienia', 'Wróć do Eris Płomień Przystani we Wschodnich Plagowiskach.', '', '', '', '', 0),
(8859, 'koKR', 'Sekrety Kolosa – Zora', 'Moi słudzy omal nie zginęli, zdobywając tę próbkę. Musisz się koniecznie pospieszyć! Lord Maxwell Tyrosus niecierpliwie czeka na świeżą próbkę skorupy. Uważa, że sekrety tego Kolosa mogą nam pomóc w wojnie z Plagą!$B$BCzemu jeszcze tu stoisz?! Do Kaplicy Świetlistej Nadziei! Tak, zostaniesz sowicie $gnagrodzony:nagrodzona; za swoje wysiłki...$B', 'Zanieś Skorupę Kolosa z Zory lordowi Maxwellowi Tyrosusowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.$B', '', '', '', '', '', '', 0),
(8945, 'koKR', 'Błaganie umarłego', 'Udzielę ci informacji, o które prosisz, $N. Ale są pilniejsze sprawy.$B$BMoja ukochana żona została pojmana przez nieumarłe ścierwa Zerwikrusza.$B$BStanowczo sprzeciwiałem się, by przyłączyła się do głupiej krucjaty Argentowego Brzasku, ale to już nie ma znaczenia. Musisz dokończyć to, czego ja próbowałem dokonać – musisz wyrwać Ysidę ze szponów barona!', 'Wejdź do Stratholmu i uwolnij Ysidę Harmon z rąk barona Zerwikrusza.', '', 'Wróć do Ysidy Harmon w Stratholmie.', 'Ysida uwolniona', '', '', '', 0),
(8946, 'koKR', 'Dowód życia', 'To najokrutniejszy los, że mój ukochany zginął, próbując mnie ratować. A jednak twierdzisz, że potrafisz z nim rozmawiać.$B$BZanieś mu ten medalion jako dowód, że nic mi nie jest. Nie może dłużej pozostawać na tym świecie; moje serce by tego nie zniosło.$B$BŻegnaj, $N. Zawsze będę twoją dłużniczką.', 'Zanieś Medalion Ysidy Anthionowi Harmonowi we Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(8947, 'koKR', 'Dziwna prośba Anthiona', 'Nie zdawaliśmy sobie sprawy ze znaczenia medalionu Valthalaka, więc podzieliliśmy go razem z resztą łupów. Pierwszą część wziął krasnolud imieniem Theldren. Próbowałem mu ją odebrać, a on omal mnie nie zatłukł. Będziesz $gmusiał:musiała; odebrać mu ten fragment siłą.$B$BOstatnio słyszałem, że został gladiatorem u krasnoludów z Czarnorytu. Zmuszenie go do walki z tobą będzie jednak nie lada wyzwaniem.$B$BZbierz dla mnie następujące materiały. Będą ci potrzebne.', 'Przynieś 3 Sztabki czarnorytu, 20 sztuk Zaklętej skóry, 3 bele Księżycowej tkaniny i 4 Wyprawione chropowate skóry Anthionowi Harmonowi we Wschodnich Plagowiskach.', '', 'Wróć do Anthiona Harmona w Stratholmie we Wschodnich Plagowiskach.', '', '', '', '', 0),
(8948, 'koKR', 'Stary przyjaciel Anthiona', 'Theldren nie należy do tych, którzy chętnie stają do uczciwej walki. Nadałem temu sztandarowi barwy jego rodu.$B$BZ pomocą dodatkowych czarów ten sztandar sprowokuje go w sposób, któremu nie zdoła się oprzeć.$B$BMój stary znajomy, Falrin, zna dokładną procedurę. Ma szczególny sposób na... wyprowadzanie ludzi z równowagi. Znajdziesz go w bibliotece w Srogomłotach.', 'Zanieś niekompletny Sztandar prowokacji Falrinowi Kształtującemu Drzewa w bibliotece w Srogomłotach.', '', '', '', '', '', '', 0),
(9015, 'koKR', 'Wyzwanie', 'Słuchaj uważnie, $N. Aby sztandar zadziałał tak, jak trzeba, musisz wejść do Kręgu Prawa w Otchłani Czarnej Góry. Pozwól, by osądził cię najwyższy sędzia Ponurokamień, i na znak buntu wbij sztandar mocno w ziemię.$B$BTwoja ofiara nie zdoła się powstrzymać i rzuci się w wir walki, pałając chęcią zmierzenia się z tobą. Gdy zdobędziesz to, czego szukasz, wróć do Anthiona.', 'Udaj się do Kręgu Prawa w Otchłani Czarnej Góry i umieść Sztandar prowokacji w jego środku, gdy najwyższy sędzia Ponurokamień będzie ogłaszał twój wyrok. Zabij Theldrena i jego gladiatorów, a następnie wróć z pierwszą częścią amuletu lorda Valthalaka do Anthiona Harmona we Wschodnich Plagowiskach.', '', 'Wróć do Anthiona Harmona w Stratholmie we Wschodnich Plagowiskach.', 'Drużyna Theldrena pokonana', '', '', '', 0),
(9031, 'koKR', '', 'W tym amulecie uwięziono duszę Valthalaka. W swojej chciwości głupio podzieliliśmy go na trzy części, nie wiedząc, jaka klątwa nas czeka.$B$BJedynym sposobem, by powstrzymać zaklęcie Valthalaka, jest ponowne złożenie medalionu. Wróć do Deliany i powiedz jej, że Bodley to jej jedyna nadzieja na odnalezienie pozostałych części.$B$BJa zaś wreszcie spocznę w pokoju. Życzę ci powodzenia, a będzie ci potrzebne!', 'Porozmawiaj z Mokvarem w Orgrimmarze.', '', '', '', '', '', '', 0),
(9033, 'koKR', 'Echa wojny', 'Pięć lat od ostatniej wojny...$B$BZginęły dziesiątki tysięcy ludzi, a po co? Zagrożenia nigdy nie zażegnano do końca.$B$BI oto Król Lisz znów się budzi... Jego potakiwacz, Kel\'Thuzad, gromadzi siły do kolejnego ataku na nasze ziemie.$B$BNie pozwolimy na to! Udowodnij swoje oddanie. Udowodnij, że jesteś $ggotów:gotowa; narazić życie i zdrowie, by powstrzymać to szaleństwo, a połączona potęga Brzasku i Krucjaty będzie na twoje skinienie.$B$BWejdź do Naxxramas i zniszcz Plagę w jego wnętrzu...', 'Dowódca Eligor Zwiastun Świtu w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce, żebyś $gzabił:zabiła; 5 żywych monstrów, 5 kamiennoskórych gargulców, 8 kapitanów rycerzy śmierci i 3 jadowitych tropicieli.', '', 'Wróć do dowódcy Eligora Zwiastuna Świtu we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9045, 'koKR', 'Nakrycie głowy odkupienia', 'Szczątki naszych poległych bohaterów znajdziesz na zwłokach Władców Naxxramas. Przynieś mi te zbezczeszczone pamiątki wraz ze skrawkami płyty zniszczonej wojną i materiałami zdolnymi przywrócić życie przeklętej zbroi, a wykuję dla ciebie wspaniały element zbroi.', 'Dowódca Eligor Zwiastun Świtu w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach wykona Nakrycie głowy odkupienia, jeśli przyniesiesz mu: 1 Zbezczeszczone nakrycie głowy, 15 Skrawków płyty zniszczonej wojną, 5 Sztabek arkanitu i 2 Wyprawione chropowate skóry.', '', 'Wróć do dowódcy Eligora Zwiastuna Świtu we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9121, 'koKR', 'Straszliwa cytadela – Naxxramas', 'W głębi Plagowego Lasu znajduje się wejście do straszliwej cytadeli Naxxramas. Dotąd wszystkie próby wejścia do środka udaremniały magiczne osłony nałożone na runiczny portal. Aż do teraz.$B$BOpracowaliśmy sposób, by dostać się do środka za pomocą tajemnego maskowania – starego zaklęcia Kirin Toru z kilkoma moimi poprawkami. Ponieważ twojemu oddaniu dla sprawy Brzasku sporo brakuje, $N, cena będzie wysoka. Możesz odmówić i wrócić po zniżkę, gdy zdobędziesz status Czczony lub Wywyższony.', 'Arcymagini Angela Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 5 Tajemnych kryształów, 2 Kryształów Nexusa, 1 Kuli prawości i 60 sztuk złota. Musisz też mieć status Szanowany u Argentowego Brzasku.$B', '', 'Wróć do arcymagini Angeli Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9122, 'koKR', 'Straszliwa cytadela – Naxxramas', 'W głębi Plagowego Lasu znajduje się wejście do straszliwej cytadeli Naxxramas. Dotąd wszystkie próby wejścia do środka udaremniały magiczne osłony nałożone na runiczny portal. Aż do teraz.$B$BOpracowaliśmy sposób, by dostać się do środka za pomocą swego rodzaju trwałego tajemnego maskowania – starego zaklęcia Kirin Toru z kilkoma moimi poprawkami. Trzeba jednak przyznać, że maskowanie jest kosztowne. Ponieważ twoje oddanie dla sprawy Brzasku jest godne podziwu, jesteśmy gotowi pokryć część tych kosztów.', 'Arcymagini Angela Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 2 Tajemnych kryształów, 1 Kryształu Nexusa i 30 sztuk złota. Musisz też mieć status Czczony u Argentowego Brzasku.', '', 'Wróć do arcymagini Angeli Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9123, 'koKR', 'Straszliwa cytadela – Naxxramas', 'W głębi Plagowego Lasu znajduje się wejście do straszliwej cytadeli Naxxramas. Dotąd wszystkie próby wejścia do środka udaremniały magiczne osłony nałożone na runiczny portal. Aż do teraz.$B$BOpracowaliśmy sposób, by dostać się do środka za pomocą swego rodzaju trwałego tajemnego maskowania – starego zaklęcia Kirin Toru z kilkoma moimi poprawkami. Trzeba jednak przyznać, że maskowanie jest kosztowne; twoje oddanie dla sprawy Brzasku jest jednak niezachwiane! Zrzekamy się wszelkich opłat.', 'Arcymagini Angela Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach udzieli ci Tajemnego maskowania bez opłat. Musisz mieć status Wywyższony u Argentowego Brzasku.', '', '', '', '', '', '', 0),
(9124, 'koKR', 'Zbroja tropiciela krypt sama się nie zrobi...', 'Chcesz zarobić jedną z tych błyszczących monet?$B$B<Leopold unosi Odznakę krucjaty.>$B$BMam mały problem, w którym możesz mi pomóc, $N. Widzisz, robię Zbroję tropiciela krypt dla tych, którzy są na tyle szaleni, by zapuszczać się do Naxxramas. Dostarczają mi podstawowe materiały na zbroję, ale zawsze brakuje mi części biesów z krypt. Przynieś mi pakunek części, a zapłacę ci odznaką – do wykorzystania u kwatermistrza.', 'Łowczy Leopold w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 30 Części biesa z krypt.', '', 'Wróć do łowczego Leopolda w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9125, 'koKR', 'Części biesa z krypt', '', '', '', 'Wróć do łowczego Leopolda we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9126, 'koKR', 'Kości dla kościanej kosy', 'Wzór Zbroi kościanej kosy Don Julia wymaga fragmentów kości – mnóstwa fragmentów kości. Ci, którzy są na tyle szaleni, by zapuszczać się do Naxxramas, dostarczają mi dość podstawowych materiałów na zbroję, ale ciągle szukam kolejnych fragmentów kości Plagi.$B$BTo jak? Masz ochotę pobrudzić sobie ręce i przy okazji zniszczyć trochę Plagi? Same korzyści.', 'Rohan Zabójca w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 30 Fragmentów kości.$B', '', 'Wróć do Rohana Zabójcy w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9127, 'koKR', 'Fragmenty kości', '', '', '', 'Wróć do Rohana Zabójcy we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9128, 'koKR', 'Równanie żywiołów', 'Witaj, $gposzukiwaczu:poszukiwaczko; przygód! Szukasz pracy? Tym, których zatrudniam, płacę odznakami. Odznaki można wymienić u kwatermistrza na potężne przedmioty.$B$BWystarczy, że przyniesiesz mi tyle rdzeni żywiołów, ile zdołasz unieść. Im więcej, tym lepiej!$B$BZnajdziesz je przy żywiołakach wszelkich kształtów i rozmiarów, które żyją na całym naszym świecie.', 'Arcymagini Angela Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 30 Rdzeni żywiołów.$B', '', 'Wróć do arcymagini Angeli Dosantos w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9129, 'koKR', 'Rdzeń żywiołów', '', '', '', 'Wróć do arcymagini Angeli Dosantos we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9131, 'koKR', 'Rynsztunek pancernika', '$GWidziałeś:Widziałaś; kiedyś zbroję pancernika, $N? Nie, oczywiście, że nie. Jesteś jeszcze $gchłopaczkiem:dziewczynką; – smarkaczem. Powiem ci, to wspaniała rzecz.$B$BPewnie zastanawiasz się, co to wszystko ma wspólnego z tobą, co? Powiem ci, żółtodziobie: potrzebuję złomu z czarnorytu i jestem gotów zapłacić, żeby zdobyć go jak najwięcej.$B$BPotrzebuję złomu, by złożyć komplety zbroi pancernika dla naszych czempionów. Przynieś mi złom i dostaniesz zapłatę.', 'Korfax w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 30 sztuk Złomu z czarnorytu.', '', 'Wróć do Korfaxa, Czempiona Światłości, we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9132, 'koKR', 'Złom z czarnorytu', '', '', '', 'Wróć do Korfaxa, Czempiona Światłości, we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9136, 'koKR', 'Dzika flora', 'Wytwarzam dla dzielnych bohaterów, którzy wkraczają do Naxxramas, szczególny rodzaj zbroi, zwany zbroją wędrowca snów. Dostarczają mi większość potrzebnych materiałów, ale zawsze szukam kogoś, kto potrafi zdobyć dzikie liście paproci z roślin naszego świata.$B$BMożesz uważać tę pracę za niegodną ciebie, ale bez liści paproci nie da się zrobić tej zbroi.$B$BMogę też zapłacić ci wybraną przez ciebie odznaką, bo fundusze dostarczają mi zarówno Brzask, jak i Krucjata.$B', 'Rayne w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce 30 Dzikich liści paproci.', '', 'Wróć do Rayne przy Wieży Wschodniego Muru we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9137, 'koKR', 'Dzikie liście paproci', '', '', '', 'Wróć do Rayne we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9141, 'koKR', 'Mówią na mnie „Kogut”', 'Chcesz zamówienia? Co? Myślisz, że dam ci rozchwytywane zlecenie tylko za to, że się $gpojawiłeś:pojawiłaś;? Nie sądzę, żółtodziobie. Rzemieślnicy z całego świata licytują się o robotę tu, na linii frontu.$B$BJeśli chcesz zlecenia, pokaż mi, że jesteś $ggotów:gotowa; przelać krew za sprawę. Przynieś mi żeton męstwa, to pogadamy.$B$BA jest tylko jeden sposób, żeby dostać te żetony w twoje brudne łapki żółtodzioba – bierz się do zabijania.', 'Dowódca wypraw Metz w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach chce Żeton męstwa Argentowego Brzasku.$B', '', 'Wróć do dowódcy wypraw Metza we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9142, 'koKR', 'Zamówienie rzemieślnicze', '', '', '', 'Wróć do dowódcy wypraw Metza we Wschodnich Plagowiskach.', '', '', '', '', 0),
(9165, 'koKR', 'List żelazny', 'Gdyby nie pomoc poszukiwaczy przygód, moja karawana nigdy by tu nie dotarła! Plaga wyłaziła z każdej szpary, żeby nas powstrzymać przed dotarciem tutaj.$B$B<Strażnik Didier ociera czoło.>$B$BTeraz musimy tu zaczekać na przybycie feldmarszałka Chambersa. Podpisze twój list żelazny, który zaniesiesz dowódcy wypraw Metzowi w Kaplicy Świetlistej Nadziei.$B$BI, $N, uważaj, co mówisz przy Chambersie. To typ, który „odgryzie ci głowę i napluje do tchawicy” – tyle że on naprawdę to zrobi...', 'Dostarcz podpisany List żelazny dowódcy wypraw Metzowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.', '', '', '', 'List żelazny podpisany', '', '', 0),
(9178, 'koKR', 'Zamówienie rzemieślnicze – gęsty obciążnik', 'Okaziciel tego zamówienia ma prawo do zapłaty w postaci wybranej przez siebie odznaki po wykonaniu zleconego zamówienia.$B$BZamówienie BS-091:$B$BGęsty obciążnik: 120 szt.$B$BWszystkie wykonane zamówienia należy dostarczać mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.$B$BW razie naruszenia lub uszkodzenia umowa traci ważność.$B$B– Dowódca wypraw Metz, Argentowy Brzask', 'Dostarcz mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach: Gęsty obciążnik (120 szt.) oraz Zamówienie rzemieślnicze – gęsty obciążnik.', '', '', '', '', '', '', 0),
(9179, 'koKR', 'Zamówienie rzemieślnicze – napierśnik cesarskiego pancerza', 'Okaziciel tego zamówienia ma prawo do zapłaty w postaci wybranej przez siebie odznaki po wykonaniu zleconego zamówienia.$B$BZamówienie BS-428:$B$BNapierśnik cesarskiego pancerza: 3 szt.$B$BWszystkie wykonane zamówienia należy dostarczać mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.$B$BW razie naruszenia lub uszkodzenia umowa traci ważność.$B$B– Dowódca wypraw Metz, Argentowy Brzask', 'Dostarcz mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach: Napierśnik cesarskiego pancerza (3 szt.) oraz Zamówienie rzemieślnicze – napierśnik cesarskiego pancerza.', '', '', '', '', '', '', 0),
(9181, 'koKR', 'Zamówienie rzemieślnicze – wulkaniczny młot', 'Okaziciel tego zamówienia ma prawo do zapłaty w postaci wybranej przez siebie odznaki po wykonaniu zleconego zamówienia.$B$BZamówienie BS-697:$B$BWulkaniczny młot: 3 szt.$B$BWszystkie wykonane zamówienia należy dostarczać mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach.$B$BW razie naruszenia lub uszkodzenia umowa traci ważność.$B$B– Dowódca wypraw Metz, Argentowy Brzask', 'Dostarcz mistrzowi sfory Kamieniotłukowi w Kaplicy Świetlistej Nadziei we Wschodnich Plagowiskach: Wulkaniczny młot (3 szt.) oraz Zamówienie rzemieślnicze – wulkaniczny młot.', '', '', '', '', '', '', 0),
