(9205, 'koKR', 'Realizujesz zamówienie, $N?', 0),
(9206, 'koKR', 'Realizujesz zamówienie, $N?', 0),
(9211, 'koKR', 'Gdyby nie ci strażnicy Argentowego Brzasku, $gbyłbyś:byłabyś; plamą na tej podłodze.\n', 0),
(9213, 'koKR', '<Mataus ziewa.>$B$BPrecz, owadzie, chyba że masz coś dla mnie.', 0),
(9221, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9222, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9223, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9224, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9225, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
