(9227, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9228, 'koKR', 'Wybieraj ostrożnie. Zwrotów nie przyjmujemy.', 0),
(9232, 'koKR', 'Nie $gspotkałeś:spotkałaś; przypadkiem Omariona, co?', 0),
(9233, 'koKR', 'Czy to jest to, co myślę?$B$B<Wilhelmowi chyba cieknie ślinka.>', 0),
(9234, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9235, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9236, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
