(9242, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9243, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9244, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9245, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9246, 'koKR', '$GPrzyniosłeś:Przyniosłaś; materiały?', 0),
(9664, 'koKR', 'Gdy wieże znajdą się pod naszą kontrolą, wkrótce zdołamy otoczyć Porzuconych. A potem to już tylko kwestia czasu, aż ich zmiażdżymy.', 0),
(9665, 'koKR', 'Muszą być głupcami, skoro myślą, że pozwolimy im założyć bazy tak blisko jednej z naszych stolic.$B$BBędziemy przerzedzać ich szeregi, aż podkulą ogony i wycofają się z powrotem na południe.', 0),
(13166, 'koKR', 'Acherus będzie nasz!', 0);
