INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2411, 'koKR', 'OoOoOoO OOoOOoo OOOoOoo OOoOooO OOoOOoO OOooooO Oooooo OooOOOO OOoOOOo OOoOOoo OOoOooO OOoOOOo OOooOoO Oooooo OooOOOo OOooooO OOOoooo OOooooO Oooooo OoOoOOo OOooooO OOoOOoo OOoOOoo OOooOoO OOOOooO Oooooo OooOoOO OOoOOOo OOoOooO OOooOOO OOoOooo OOOoOoo OOOooOO Oooooo OOoOOOO OOooOOo Oooooo OooooOO OOoOooo OOooooO OOoOOOO OOOooOO', 0),
(2431, 'koKR', 'Data wpisu: nieznana\n\n\n\nImię: Nathanos Marris, człowiek, lord tropicieli Lordaeronu.\n\n\n\nWpis:\n\n\n\nOdnotowuję sprzeciw Kael\'thasa Słońcobieżcy wobec mojej decyzji o przyjęciu Nathanosa Marrisa do zakonu. Należy też odnotować, że Nathanos – choć jest człowiekiem – to jeden z najbardziej utalentowanych tropicieli, jakich miałam przyjemność szkolić.\n\n\n\n(ciąg dalszy)', 0),
(2471, 'koKR', 'Przez tysiąclecia odgradzaliśmy się od obcych. Jako pierwsza z nas przyznam, że w przeszłości popełniono błędy. Ludzie nigdy nie powinni byli zetknąć się z magią. Nie zaprzeczam temu, ale nie skażę nas na to odizolowane istnienie za pomyłki naszych poprzedników. Współistnienie Quel\'dorei z innymi rasami tego świata może przynieść wiele dobrego. Musimy okazywać tolerancję.\n\n\n\n(ciąg dalszy)', 0),
(2472, 'koKR', 'Tymi słowy odrzucam zatem prośbę Kaela w sprawie Nathanosa Marrisa. Okaże się on nieocenionym sojusznikiem. Zapamiętajcie moje słowa.\n\n\n\nPodpisano,\n\n\n\nSylwana Bieżywiatr\n\nGenerał tropicieli Srebrnej Luny', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(8358, 'koKR', '', 'Witaj, $N. Wybacz mi, proszę, właśnie rozmawiam z Rimblatem. Uważa, że nawet tę ziemię można jeszcze ocalić.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40101, 'koKR', 'Chwała Światłości, ktoś wreszcie odpowiedział na wezwanie.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40102, 'koKR', '<Eris kiwa głową>$B$BOko widziało tak wiele okropieństw i cudów.$B$BUkazuje to, co uzna za najbardziej odpowiednie dla tego, kto w nie patrzy.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40103, 'koKR', 'Owszem. Oko nigdy się nie myli.$B$BJesteś przecież $gkapłanem:kapłanką;. I to $gpotężnym:potężną;, skoro Oko ukazało ci to straszliwe wspomnienie.$B$BPrzybywasz po odkupienie, choć $gsam:sama; nie zdajesz sobie z tego sprawy... Prawda?', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40104, 'koKR', 'Wiem, że to zrobisz, $N.$B$BJa sama jestem kapłanką, choć w przeciwieństwie do ciebie dawno już odeszłam z tego świata. Mój duch jednak pozostał tutaj, podobnie jak duchy tysięcy ludzi brutalnie zamordowanych przez szalonego księcia, Arthasa Menethila, i jego legion nieumarłych.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40105, 'koKR', 'Nigdy nie mówiłam, że przybywasz tu, by odkupić siebie, $N. Przybywasz, by odkupić mnie i niewinnych zamordowanych podczas ucieczki ze Stratholmu.$B$BMój duch i duchy tych, którzy zginęli, są tu uwięzione, przeklęte, by bez końca przeżywać na nowo własną tragiczną śmierć.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(40106, 'koKR', 'Musisz dokonać tego, czego ja nie zdołałam: ocalić wieśniaków, których wyrżnięto, gdy uciekali ze Stratholmu.$B$BBędą iść w stronę światła, a ty musisz zapewnić im przetrwanie. Jeśli zbyt wielu zginie, nasze przeklęte istnienie będzie trwać dalej – poniesiesz porażkę.$B$BSprawdzona zostanie każda umiejętność, modlitwa i zaklęcie, jakie $gpoznałeś:poznałaś;. Niech Światłość cię chroni, $N.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(30212, 0, 'koKR', 'Oko mnie tu przywiodło, Eris.', ''),
(30213, 0, 'koKR', 'I to właśnie było dla mnie odpowiednie?', ''),
(30214, 0, 'koKR', 'Naprawdę nie $gwiedziałem:wiedziałam;, czego się spodziewać, Eris. Jeśli tego się ode mnie oczekuje, użyję swoich mocy, by ci pomóc.', ''),
(30215, 0, 'koKR', 'Te dni już minęły, Eris.', ''),
(30216, 0, 'koKR', 'Jak więc mogę pomóc?', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(10432, 0, 2, 'koKR', 'Przygotowując posiłek dla smoka, pamiętajcie, by torturować więźnia na jego oczach. Smok dobrze reaguje na rozrywkę przed posiłkiem.'),
(10432, 0, 3, 'koKR', 'Siły Króla Lisza rosną. Nasz harmonogram musi koniecznie wspierać jego plany.'),
(10432, 0, 7, 'koKR', 'Czekamy na dostawę jaj czarnych smoków z Płonących Stepów. Wierzymy, że ich badanie znacząco poszerzy naszą wiedzę.'),
(10432, 1, 0, 'koKR', 'Co to ma być?! Jak śmiesz!'),
(14494, 2, 0, 'koKR', 'Ponieśliśmy porażkę! Wieśniaków nie ocalono!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(6260, 'koKR', 'Opuść to miejsce!', '', 0),
(6427, 'koKR', 'Dziękuję! $GUwolniłeś:Uwolniłaś; mnie!', 'Dziękuję! $GUwolniłeś:Uwolniłaś; mnie!', 0),
(6428, 'koKR', 'Och, dziękuję! Tak długo trwał dla mnie ten koszmar...', 'Och, dziękuję! Tak długo trwał dla mnie ten koszmar...', 0),
(6429, 'koKR', 'Nareszcie moja dusza jest wolna!', 'Nareszcie moja dusza jest wolna!', 0),
(6430, 'koKR', 'Dziękuję! Bitwa o Włości Darrow przypieczętowała mój los, ale ty mnie $guwolniłeś:uwolniłaś;!', 'Dziękuję! Bitwa o Włości Darrow przypieczętowała mój los, ale ty mnie $guwolniłeś:uwolniłaś;!', 0),
(6431, 'koKR', 'Ach! Proszę, jeśli spotkasz kogoś, kto przeżył Włości Darrow, powiedz mu, że moja dusza jest wolna!', 'Ach! Proszę, jeśli spotkasz kogoś, kto przeżył Włości Darrow, powiedz mu, że moja dusza jest wolna!', 0),
(6464, 'koKR', 'Oni podają mi zwłoki, a ja wrzucam je do dołu.', '', 0),
(6505, 'koKR', '', 'Duchy Wysoko Urodzonych! Zaznajcie spokoju! Kryształ Zin-Malor znów jest cały!', 0),
(6506, 'koKR', '', 'Przeklęte duchy! Porzućcie przeszłość! Kryształ Zin-Malor już was nie więzi!', 0),
(6507, 'koKR', '', 'Duchy Wysoko Urodzonych! Możecie teraz spocząć! Klątwa kryształu was uwalnia!', 0),
(6878, 'koKR', 'Potrzebuję kolejnego Zlecenia Argentowego Brzasku.', 'Potrzebuję kolejnego Zlecenia Argentowego Brzasku.', 0),
(6882, 'koKR', '', 'Witaj, $N. Jestem Miranda Breechlock – jedna z nielicznych upoważnionych kwatermistrzyń Brzasku od sprzętu i zaopatrzenia.$B$BWalcząc ze złem na nasze zlecenie – i zdobywając przy tym nasz szacunek i zaufanie – otrzymasz od księcia Zverenhoffa żetony męstwa. Żetony służą dwóm celom: możesz dzięki nim podnieść swoją pozycję w naszych szeregach albo użyć ich jako zapłaty za wyjątkowe przedmioty.$B$BW miarę jak twoja pozycja w Brzasku będzie rosła, przekonasz się, że udostępnimy ci więcej przedmiotów.', 0),
(7180, 'koKR', 'Czy mogę spytać, co ty tu robisz? Włóż strój ucznia i ucz się!', '', 0),
(7181, 'koKR', 'Cisza! Myślisz, że nasze zarażone smoki same się wyklują i wytresują?', '', 0),
(7182, 'koKR', 'Przybywasz z Płonących Stepów? Masz moje jaja czarnych smoków?', '', 0),
(7188, 'koKR', 'A teraz, jeśli otworzycie podręcznik na stronie 34, zobaczycie ilustrację krasnoluda poddawanego sekcji...', '', 0),
(7191, 'koKR', 'Nasz najstarszy lęg smoków jest jeszcze daleki od dojrzałości, ale dzięki cierpliwości i nauce jesteśmy pewni, że stado wkrótce będzie gotowe.', '', 0),
(7192, 'koKR', 'Podczas wczorajszej wycieczki Marduk pokazał nam, że smoki tolerują mięso niedawno zabitych humanoidów, ale tylko jeśli umierały powoli i boleśnie.', '', 0),
(7193, 'koKR', 'Jutro zaczniemy szkolenie najbardziej obiecujących smoków, więc nie zapomnijcie gryzaków.', '', 0),
(7197, 'koKR', '', 'Plagowiska to doskonałe miejsce, by uderzyć w Plagę!', 0),
(7198, 'koKR', 'Mogę dostać kolejny Gambit Brzasku, Betino? Chcę go jeszcze raz przetestować...', 'Mogę dostać kolejny Gambit Brzasku, Betino? Chcę go jeszcze raz przetestować...', 0),
(7276, 'koKR', 'Jako członek Ligi Odkrywców szukam w tej okolicy artefaktów. Podobno w Zimozdroju można znaleźć przedmioty o wielkiej mocy magicznej... Większość jest pilnie strzeżona.', '', 0),
(7308, 'koKR', '', 'Taki sssmutek... Przeszłośśści nie da się cofnąć...', 0),
(7309, 'koKR', '', 'Nie zapomnę, czego łeśśś:dokonałaśśś;...$B$BProszę, zossstaw mnie...', 0),
(7595, 'koKR', '', 'Zabójcy! Straże! Straże!', 0),
(7596, 'koKR', '', 'Wyczuwam niebezpieczeństwo przed nami.', 0),
(7597, 'koKR', '', 'Plecy mnie wykończą.', 0),
(7598, 'koKR', '', 'Te rozkazy muszą dotrzeć do najwyższego generała Abbendis!', 0),
(7599, 'koKR', '', 'Jeśli polegnę, weź moją sakwę. Dopilnuj, by dotarła do najwyższego generała.', 0),
(7620, 'koKR', 'Zanim przyszła Plaga, prowadziłem świetny interes. Kupowałem i sprzedawałem wszystko. Wszystko!$B$BA moje ceny były SZALONE!$B$BZapytaj kogokolwiek. Kogokolwiek, kto jeszcze żyje.', '', 0),
(7621, 'koKR', 'Cześć, $N! łeś:Przyszłaś; coś kupić? A może coś sprzedać?$B$BNigdzie nie znajdziesz lepszych cen, albo nie nazywam się Augustus Dotknięty!', '', 0),
(7623, 'koKR', 'Tak, Augustusie. Chciał$gbym:abym; pohandlować.', 'Tak, Augustusie. Chciał$gbym:abym; pohandlować.', 0),
(7627, 'koKR', 'Nigdzie nie znajdziesz lepszych cen!', '', 0),
(7628, 'koKR', 'Jestem Augustus, a moje ceny są SZALONE!', '', 0),
(7629, 'koKR', 'Jestem Augustus! Chcesz to mieć, to ja to mam! Chcesz to sprzedać, to ja to chcę!', '', 0),
(8332, 'koKR', '', 'Zaczekaj, proszę, a ja spróbuję połączyć odłamki, by znów stanowiły całość.', 0),
(8333, 'koKR', '', 'Ishnu... Oshalan thara dormil... Anu\'dorin...', 0),
(8338, 'koKR', '', 'Tak, zdołałam na nowo scalić relikwię, $N.', 0),
(8339, 'koKR', '', 'Proszę, opuść to miejsce, $N. Nic nie wiesz o tym, co nas dręczy...', 0),
(8340, 'koKR', 'Gdzie mogę zdobyć Zaklęte torium?', 'Gdzie mogę zdobyć Zaklęte torium?', 0),
(8341, 'koKR', 'Gdzie znajdę Kryształowe odnowienie?', 'Gdzie znajdę Kryształowe odnowienie?', 0),
(8370, 'koKR', '', 'Po co tu $gprzyszedłeś:przyszłaś;, $N?', 0),
(8371, 'koKR', '', 'Mój lud jest równie strzaskany jak relikwia, którą chcesz naprawić.', 0),
(9655, 'koKR', '', 'Bądź uleczony!', 0),
(9728, 'koKR', '', 'Jesteśmy ocaleni! Wieśniacy umknęli Pladze!', 0),
(10458, 'koKR', 'Betino, poproszę nową Pieczęć Brzasku!', 'Betino, poproszę nową Pieczęć Brzasku!', 0),
(10462, 'koKR', 'Betino, poproszę nową Runę Brzasku!', 'Betino, poproszę nową Runę Brzasku!', 0),
(11907, 'koKR', 'Co znowu? Nie widzisz, że jestem dość zajęty?', '', 0),
(11930, 'koKR', '', 'Na razie nic mi nie będzie, nie martw się o mnie. Znajdę jakieś wyjście, gdy tylko odprawię w tej komnacie kilka rytuałów oczyszczenia. Plugawa magia skaziła to miejsce, $N.', 0),
(11931, 'koKR', '', 'Udało ci się... $gzabiłeś:zabiłaś; barona Zerwikrusza! Argentowy Brzask usłyszy o twoich mężnych czynach!', 0),
(11940, 'koKR', '', 'Powiadają, że Kel\'Thuzad szuka legendarnego Atiesza, Wielkiego Kostura Strażnika.$B$BTak, tego samego kostura, który dzierżył niegdyś Medivh.', 0),
(11941, 'koKR', 'My, z Bractwa Światłości, nie jesteśmy tak pobłażliwi jak nasi bracia, gdy przychodzi do wymierzania sprawiedliwości tym, którzy krzywdzą ten świat.', '', 0),
(11942, 'koKR', 'Król Lisz próbuje dać o sobie znać w naszym świecie. Nie wolno do tego dopuścić.\n', '', 0),
(11943, 'koKR', 'Czym jest Bractwo Światłości? Cóż... W głębi duszy wszyscy jesteśmy członkami Krucjaty Argentu – członkami Krucjaty Argentu, których nie krępują moralność, poczucie winy i bezużyteczne ludzkie emocje.', '', 0),
(11944, 'koKR', '', 'Argentowy Brzask to może i bezsilni idealiści, ale ich zaślepiony przywódca wie, że nie dorównują przeciwnikowi. Przysłano mnie tu jako emisariuszkę Szkarłatnej Krucjaty. Ambasadorkę, jeśli wolisz... Wątpliwe, byśmy choćby nadszarpnęli armie Kel\'Thuzada – razem czy osobno – ale może zdołamy je powstrzymać na tyle długo, by zdarzył się jakiś cud.$B$BA ja? Zginę w bitwie...$B$B<Marjhan wzrusza ramionami.>\n', 0),
(11945, 'koKR', '', 'To cudowne, Rimblacie! Nawet ta plugawa, rozdarta ziemia nie jest nie do uleczenia.', 0),
(11946, 'koKR', 'Patrz, druidko. Ziemia wciąż oddycha. Pragnie oczyszczenia.', '', 0),
(11947, 'koKR', 'Ten tytuł jest mylący. Tak naprawdę jestem bardzo miłą osobą, kiedy się mnie bliżej pozna.', '', 0),
(11948, 'koKR', 'Prawie wysłali na to zgromadzenie mojego brata, Lokseya. On nie potrafi nawet zająć się swoimi ogarami, a co dopiero kompetentnie reprezentować Szkarłatnej Krucjaty.', '', 0),
(11949, 'koKR', 'Spodziewa...$B$B<Rimblat kaszle.>$B$BWybacz, stary nawyk. Jestem Rimblat z Kręgu Ziemi.', '', 0),
(11951, 'koKR', 'Czego chcesz, lemingu? Zejdź mi z oczu, zanim się przekonasz, czemu nazywają mnie Gniewomiotem.', '', 0),
(11960, 'koKR', 'Czym jest zbroja pancernika?', 'Czym jest zbroja pancernika?', 0),
(11961, 'koKR', 'Pierwszą zbroję pancernika wykonano wyłącznie dla szkarłatnego najwyższego lorda Mograine\'a. W pełnym rynsztunku najwyższy lord wyglądał jak demon z głębin Otchłani.$B$BO tak, było na co patrzeć, gdy Mograine wkraczał między setkę sług Plagi ze Spopielaczem wzniesionym wysoko i wychodził po drugiej stronie w chmurze pyłu i płomieni – a wrogowie leżeli w popiele u jego stóp.', '', 0),
(11963, 'koKR', 'Dopiero po jego kontrowersyjnej śmierci rycerze i wojownicy Lordaeronu zaczęli nosić podobnie wykonane zbroje na cześć poległego bohatera. Choć śmierć Mograine\'a była wielkim zwycięstwem Kel\'Thuzada, jego męczeństwo dawało się odczuć aż do końca wojny.$B$BGdzie jeden padł, wielu powstało...', '', 0),
(11964, 'koKR', 'Coś jeszcze?', 'Coś jeszcze?', 0),
(11969, 'koKR', 'Jestem, jak to się mówi, kapitalistą, $N.', '', 0),
(11978, 'koKR', 'Czym jest zbroja tropiciela krypt?', 'Czym jest zbroja tropiciela krypt?', 0),
(11979, 'koKR', 'Nadnaturalna zdolność biesa z krypt do tropienia i zabijania wroga jest przedmiotem badań i podziwu ludzi mojej profesji. Sam zabiłem tysiące tych bestii w swojej krucjacie, by oczyścić ten świat z Plagi.$B$BChoć brzydzę się biesem z krypt za jego bezlitosną naturę, jego zdolności budzą podziw. Ma swoje zadanie i wykonuje je – bardzo dobrze.', '', 0),
(11981, 'koKR', 'Znalazłem zastosowanie dla pancerza biesa z krypt i różnych części jego ciała. Łącząc te fragmenty z niektórymi zbezczeszczonymi magicznymi zbrojami utraconymi w Naxxramas, potrafię wykonać wyjątkowo lekki i bardzo zabójczy komplet zbroi.', '', 0),
(11983, 'koKR', 'Co sprowadza taurena na Plagowiska?', 'Co sprowadza taurena na Plagowiska?', 0),
(11984, 'koKR', 'W ostatniej wojnie walczyli też taureni. Szamanów wysłano, by bronili tego świata przed najazdem Plagi. Większość straciła życie. Wielu innych rozerwano na strzępy, a części ich ciał posłużyły do plugawych eksperymentów w tej przeklętej cytadeli. Opłakuję ich odejście, ale moje serce wzbiera dumą z ich odwagi.', '', 0),
(11986, 'koKR', 'Byłem wtedy młodym taurenem, ledwie wkraczającym w dorosłość, ale wiedziałem, że ci, którzy stawali do bitew o naszą wolność, byli dobrze chronieni w szatach noszących imię mojego rodu.', '', 0),
(11987, 'koKR', 'Miano Kruszyciela Ziemi nosi moja rodzina od setek lat. I tak jak mój ojciec i jego ojciec przed nim, ja także odziedziczyłem prawo do tworzenia szat noszących imię mojego rodu.', '', 0),
(12003, 'koKR', 'Czym właściwie się zajmujesz, Rohanie?', 'Czym właściwie się zajmujesz, Rohanie?', 0),
(12004, 'koKR', 'Ach, jak mówi mój tytuł, jestem zabójcą na usługach Szkarłatnej Krucjaty. Dnie spędzam na eliminowaniu celów najwyższej wagi, a noce w dyskotece w Gadżetonie. Taniec to moje prawdziwe powołanie. Zabijanie tylko opłaca rachunki.', '', 0),
(12005, 'koKR', 'Co cię sprowadza do Kaplicy Świetlistej Nadziei?', 'Co cię sprowadza do Kaplicy Świetlistej Nadziei?', 0),
(12006, 'koKR', 'Dobre pytanie, $N. Za młodu byłem wolny jak ptak i niczym się nie przejmowałem. W tamtych czasach śpiewałem w kwartecie fryzjerskim z Wichrogrodu, zwanym Czterema Donami. Tam nauczyłem się wytwarzać zbroję kościanej kosy.', '', 0),
(12007, 'koKR', 'Co? Kościanej kosy?', 'Co? Kościanej kosy?', 0),
(12008, 'koKR', 'Tak, kościanej kosy. Widzisz, to nasz tenor, zrzędliwy gość znany jako Don Julio, wciągnął mnie w to wszystko. Podczas swoich podróży po Lordaeronie Don Julio nabył wiele ciekawych umiejętności, a jedną z nich było przerabianie kości poległych sług Plagi na zabójczy komplet skórzanej zbroi – idealny dla zabójcy.', '', 0),
(12009, 'koKR', 'Rany, ty chyba $gzwariowałeś:zwariowałaś;, co?', 'Rany, ty chyba $gzwariowałeś:zwariowałaś;, co?', 0),
(12010, 'koKR', 'Jestem tak samo przy zdrowych zmysłach jak każdy inny, $gkolego:panienko;. Wierz, w co chcesz, ale POTRAFIĘ wykonać tę zbroję. Jeśli cię to interesuje, może dobijemy targu. Im szybciej porzucę fach zabójcy, tym lepiej.', '', 0),
(12011, 'koKR', 'Chwila, w Gadżetonie jest dyskoteka?', 'Chwila, w Gadżetonie jest dyskoteka?', 0),
(12012, 'koKR', 'Tylko dla członków, żółtodziobie!\n', '', 0),
(12015, 'koKR', 'Witaj, Rayne. Co sprowadza Krąg Cenariona na Plagowiska?', 'Witaj, Rayne. Co sprowadza Krąg Cenariona na Plagowiska?', 0),
(12016, 'koKR', '', 'Każdego z nas przyciągnęło tu co innego, $N.$B$B<Rayne się uśmiecha.>$B$BPrzybyłam, by spotkać się z Rimblatem z Kręgu Ziemi. Ma ciekawe teorie na temat oczyszczenia tych ziem.', 0),
(12017, 'koKR', 'Czy tych ziem nie da się już uleczyć? Wyglądają na mocno zniszczone.', 'Czy tych ziem nie da się już uleczyć? Wyglądają na mocno zniszczone.', 0),
(12018, 'koKR', '', 'Nie sądzę. Rimblat już dowiódł, że z rozdartej ziemi może wyrosnąć nowe życie. Teraz musimy znaleźć sposób, by powtórzyć ten wzrost i, co ważniejsze, go podtrzymać.$B$BSkoro już tu jestem, oferuję też swoje usługi poszukiwaczom przygód wyruszającym do Naxxramas.', 0),
(12019, 'koKR', 'Jakie usługi?', 'Jakie usługi?', 0),
(12020, 'koKR', '', 'Jestem dość znaną rzemieślniczką, $N. Mając odpowiednie materiały, potrafię wykonać zbroję zwaną zbroją wędrowca snów. Druidów – a nawet niektórych szamanów – przyciągają jej magiczne właściwości. Interesuje cię to?', 0),
(12021, 'koKR', 'Czym jest Atiesz?\n', 'Czym jest Atiesz?\n', 0),
(12022, 'koKR', '', 'Tak jak Kel\'Thuzad, ja również byłam niegdyś magiem Kirin Toru. I tak jak Kel\'Thuzad, szukam legendarnego Atiesza, Wielkiego Kostura Strażnika. Nasze losy są więc splecione, $N.', 0),
(12023, 'koKR', 'Jakiego Strażnika? Nic z tego nie rozumiem.', 'Jakiego Strażnika? Nic z tego nie rozumiem.', 0),
(12024, 'koKR', '', 'Potomek Egwiny, ten, który miał być ostatnim Strażnikiem Tirisfal... Medivh.', 0),
(12026, 'koKR', '', 'To legendarna opowieść, a ja nie mam ani czasu, ani ochoty jej powtarzać. Wiedz tylko, że Medivh był ostatnim ze Strażników. Wielki kostur Atiesz był ogniskiem jego mocy i ogniskiem zepsucia.', 0),
(12027, 'koKR', 'Jakiego zepsucia?', 'Jakiego zepsucia?', 0),
(12028, 'koKR', '', 'Zepsucia upadłego tytana. Zepsucia Niszczyciela. Wszak kostur wykuto z nasienia nienawiści. I to właśnie mnie tu sprowadziło...', 0),
(12030, 'koKR', '', 'Po upadku Karazhanu Kirin Tor wysłał grupę magów, by przeszukali wieżę i zabrali wszystkie ważne przedmioty... w celach „badawczych”. Wtedy właśnie odkryto legendarny kostur i przeniesiono go do Dalaranu.', 0),
(12032, 'koKR', '', 'Potem nastąpił szereg tragicznych wydarzeń, w wyniku których zginął każdy mag Kirin Toru, który zetknął się z Atieszem.$B$BWidzisz, był to artefakt obdarzony świadomością. Świadomością nadaną mu przez Sargerasa...', 0),
(12034, 'koKR', '', '<Angela kiwa głową.>$B$BPo tych śmierciach Szóstka uznała, że najlepiej będzie zapieczętować kostur za nieprzeniknionymi barierami magii i wyznaczyć strażnika: opiekuna kostura... Tym strażnikiem miałam zostać ja.', 0),
(12035, 'koKR', 'To niepokojące. Mów dalej, proszę.', 'To niepokojące. Mów dalej, proszę.', 0),
(12036, 'koKR', '', 'Niewiele więcej jest do opowiedzenia. Dalaran został niemal doszczętnie zniszczony przez Archimonda, a kostur przepadł, zapewne roztrzaskany przez zabezpieczenia bariery.$B$BSą tacy, którzy wierzą, że to kostur ściągnął na Dalaran zemstę Archimonda.', 0),
(12037, 'koKR', 'Proszę, opowiedz mi więcej.', 'Proszę, opowiedz mi więcej.', 0),
(12038, 'koKR', '', 'Po upadku Dalaranu odeszłam z Kirin Toru. Przez lata strzegłam Atiesza, a potem jednym ciosem odebrano mi mój cel w szeregach Kirin Toru. Postanowiłam odnaleźć kostur, choćby miało to zająć całe życie. Dlatego przyłączyłam się do Argentowego Brzasku i dlatego teraz tu jestem.', 0),
(12039, 'koKR', 'Czy jest coś jeszcze?', 'Czy jest coś jeszcze?', 0),
(12040, 'koKR', '', 'Wytropiłam rozmaite fragmenty kostura na całym świecie i przy okazji odkryłam, że Kel\'Thuzad planuje go odtworzyć. Zebrał już kilka fragmentów kostura – przechowują je jego najbardziej zaufani poplecznicy.$B$BNie mogę dość mocno podkreślić, jak ważne jest, by Wielki Kostur Strażnika nie wpadł w ręce Kel\'Thuzada. Szczerze mówiąc, nie wiem, co by z tego wynikło, poza katastrofą epickich rozmiarów.', 0),
(12047, 'koKR', '', 'Twoja wiadomość do nas dotarła, dowódco, ale nasz udział w tym spotkaniu w żadnym razie nie ma aprobaty Wielkiego Krzyżowca.', 0),
(12048, 'koKR', 'Twój przywódca rezyduje u progu Naxxramas. Sądzisz, że nie odczuwa presji?\n', '', 0),
(12049, 'koKR', '%s ścisza głos do szeptu.', '', 0),
(12050, 'koKR', 'Nawet demony potrafią się bać...', '', 0),
(12051, 'koKR', 'Aktywność Plagi na Plagowiskach wzrosła dziesięciokrotnie. Otrzymujemy wieści o atakach Plagi aż z Kalimdoru! Jak sądzisz, jak do tego doszło? Jak nędzni nieumarli dokonali tego, co wcześniej uważano za niemożliwe? Czy nigdzie nie jest bezpiecznie?', '', 0),
(12052, 'koKR', '', 'Poganie będą zmuszeni zareagować. Orkowie, byczy ludzie...', 0),
(12053, 'koKR', 'Taureni.', '', 0),
(12054, 'koKR', '', 'Wszystko jedno. Odrażające, niechlujne hordziarskie ścierwo...', 0),
(12055, 'koKR', 'Brak ci taktu, komandor. To nie dziwi. Masz jednak rację, że Horda będzie zmuszona działać. I nie tylko Horda. Już nadciągają – bohaterowie z całego świata.', '', 0),
(12056, 'koKR', '', 'Za mało i za późno. Tama pękła. W najlepszym razie jesteśmy wybojem na drodze.', 0),
(12057, 'koKR', 'To po co tu jesteś? Co mamy robić, jeśli nie ma nadziei?', '', 0),
(12058, 'koKR', 'Zawsze jest jeszcze... Spopielacz.', 'Zawsze jest jeszcze... Spopielacz.', 0),
(12062, 'koKR', 'Więc po to przybyłaś? By spróbować zdobyć to, co jest przyczyną istnienia Brzasku i upadku Krucjaty? Twoje słowa rozdrapują stare rany, komandor!', '', 0),
(12063, 'koKR', 'Spopielacz nie żyje i nigdy nie będzie drugiego takiego jak on. Mniejszemu Mograine\'owi daleko do człowieka, jakim był jego ojciec. Wiesz o tym, komandor! To przecież wasze własne przywództwo odpowiada za śmierć szkarłatnego najwyższego lorda Mograine\'a.', '', 0),
(12065, 'koKR', 'To wasze przywództwo zmanipulowało pogrążone w żałobie dziecko, by spróbowało odzyskać miecz. Dziecko, które wyrosło na mężczyznę o sercu pełnym wyłącznie zemsty i nienawiści! I po co? Nie jesteście dziś ani trochę bliżej miecza niż pięć lat temu.\n', '', 0),
(12066, 'koKR', 'A mimo to sądzisz, że odzyskanie Spopielacza jakimś cudem odwróci losy bitwy? Zdradzę ci mały sekret, komandor: moc Spopielacza pochodziła od człowieka, który go dzierżył... Byłem tam, komandor. Widziałem, jak palił legiony nieumarłych w ogniu sprawiedliwości, zanim w ogóle dobył ostrza. Niestety twoja znajomość historii jest... niewystarczająca.', '', 0),
(12067, 'koKR', 'A teraz milcz i pamiętaj, gdzie jesteś, bym nie musiał powiadomić lorda Fordringa i jego rycerzy, że nie przebywasz tu już w przyjaznych zamiarach. Jestem pewien, że z wielką przyjemnością dopilnowałby twojej „pokuty”.', '', 0),
(12075, 'koKR', 'Gdzie znajdę części biesów z krypt, Leopoldzie?', 'Gdzie znajdę części biesów z krypt, Leopoldzie?', 0),
(12076, 'koKR', 'Te plugawe bestie są wszędzie.$B$BJeśli wolisz polować na otwartym terenie, większość znajdziesz w Plagowym Lesie i w Dolinie Grozy, a sporo z nich w Tunelu Sieci Grozy. Pojawiają się też w niemal każdym obozowisku Plagi we Wschodnich Plagowiskach.$B$BJeśli zaś jesteś $gzapalonym:zapaloną; $gbadaczem:badaczką; lochów, sporo ich znajdziesz w Stratholmie, a kilka odmiany nekrobiesów w Scholomancjum.', '', 0),
(12077, 'koKR', 'Gdzie znajdę fragmenty kości?', 'Gdzie znajdę fragmenty kości?', 0),
(12078, 'koKR', '$GZgłupiałeś:Zgłupiałaś;? Nie $gzauważyłeś:zauważyłaś; KOŚCISTYCH SZKIELETÓW walających się wszędzie po drodze?$B$B<Rohan wzdycha.>$B$BJeśli wolisz tereny otwarte, szkieletowe stwory znajdziesz w całych Zachodnich i Wschodnich Plagowiskach. Uwierz mi, nie przegapisz ich – one ciebie na pewno nie przegapią, jeśli tylko nadarzy się okazja.$B$BJeśli wolisz lochy, po fragmenty kości zdecydowanie warto się wybrać do Stratholmu i Scholomancjum.', '', 0),
(12086, 'koKR', 'Gdzie znajdę rdzenie żywiołów?', 'Gdzie znajdę rdzenie żywiołów?', 0),
(12087, 'koKR', '', 'Ach, dobre pytanie.$B$BJeśli wolisz polować na łonie natury, żywiołaki znajdziesz tu, na Plagowiskach, a także w Aszarze, na Płonących Stepach, w Spaczonej Kniei, w Silithusie, w Zimozdroju, a nawet w Kraterze Un\'Goro.$B$BJeśli należysz do tych, którzy śmieją się niebezpieczeństwu w twarz, może warto odwiedzić Srogomłoty. Słyszałam, że w ich murach żyje mnóstwo żywiołowych wynaturzeń. Warto też poszukać żywiołaków na usługach krasnoludów z Czarnorytu w Otchłani Czarnej Góry.', 0),
(12088, 'koKR', 'Korfaxie, gdzie znajdę złom z czarnorytu?', 'Korfaxie, gdzie znajdę złom z czarnorytu?', 0),
(12089, 'koKR', 'Czy to poważne pytanie? Naprawdę nie wiesz?$B$BJeśli należysz do tchórzy, którzy boją się zbytnio pobrudzić ręce, złom z czarnorytu znajdziesz przy stworzeniach na Płonących Stepach i w Płonącym Wąwozie.$B$BJeśli zaś jesteś $gżądnym:żądną; krwi $gposzukiwaczem:poszukiwaczką; przygód, w lochach Iglicy Czarnej Góry i Otchłani Czarnej Góry jest spory zapas złomu.', '', 0),
(12090, 'koKR', 'Rayne, gdzie szukać dzikich liści paproci?', 'Rayne, gdzie szukać dzikich liści paproci?', 0),
(12091, 'koKR', '', 'Jeśli wolisz polować na otwartym terenie, doskonałym źródłem liści są drzewce ze Spaczonej Kniei i biczownicy z Un\'Goro.$B$BJeśli zaś lubisz ryzyko, wschodnie i zachodnie skrzydło Srogomłotów zapewnią ci niemal niewyczerpany zapas dzikich liści paproci.', 0),
(12096, 'koKR', 'Mam za dużo roboty, żeby bawić się z tobą w „zgadnij, co tak śmierdzi”, $N. Mów, z czym przychodzisz, albo zejdź mi z oczu!', '', 0),
(12132, 'koKR', '', 'Proszę, dowódca zamawiał półmisek ryb. Smacznego!', 0),
(12133, 'koKR', '', 'Ojcze, ojciec zamawiał miskę owoców, prawda?', 0),
(12134, 'koKR', '', 'A dla pań pieczony prosiak z dzika. Smacznego!', 0),
(12135, 'koKR', '', 'Proszę dać znać, gdyby czegoś jeszcze było trzeba!', 0),
(12136, 'koKR', '', 'Witaj w Kaplicy Świetlistej Nadziei, $gnieznajomy:nieznajoma;.', 0),
(12137, 'koKR', 'Wyrazy uznania dla kucharza!', '', 0),
(12138, 'koKR', 'Ryba jest wyśmienita, Jessico.', '', 0),
(12139, 'koKR', 'Pyszne!', '', 0),
(12140, 'koKR', 'Dziękuję, pani Chambers.', '', 0),
(12141, 'koKR', 'Czy to mango? Zdumiewające!', '', 0),
(12142, 'koKR', 'Tym razem przeszła pani samą siebie, pani Chambers. Ani śladu pleśni!', '', 0),
(12143, 'koKR', '', 'Dziękuję, Jessico.', 0),
(12144, 'koKR', '', 'I muszę dodać, że ta suknia jest śliczna! Musisz mi powiedzieć, skąd ją masz.', 0),
(12145, 'koKR', '', 'W rzeczy samej... śliczna suknia, Jessico.', 0),
(12146, 'koKR', '', 'Dzik jest wyborny!', 0),
(12147, 'koKR', '', 'Och, bardzo soczysty. Wielkie dzięki, pani Chambers.', 0),
(12148, 'koKR', 'Nasze karawany wyruszają jakieś dwa razy dziennie, ale niech mnie, jeśli Plaga nie stawia na głowie, żeby Didier i jego muły nie dowieźli dostaw na front. Najbardziej zwariowana rzecz, jaką widziałem. Gdybyśmy tylko mieli jakichś bohaterskich poszukiwaczy przygód do ochrony dostaw...', '', 0),
(12152, 'koKR', 'Mam za dużo do zrobienia i za mało czasu, $N! Proszę, zejdź mi z drogi.', 'Mam za dużo do zrobienia i za mało czasu, $N! Proszę, zejdź mi z drogi.', 0),
(12153, 'koKR', 'Mam za dużo do zrobienia i za mało czasu, $N! Proszę, zejdź mi z drogi.$B$BJeśli $gzaraziłeś:zaraziłaś; się czerwim śluzem albo ghulią zgnilizną, może zdołam ci pomóc.', 'Mam za dużo do zrobienia i za mało czasu, $N! Proszę, zejdź mi z drogi.$B$BJeśli $gzaraziłeś:zaraziłaś; się czerwim śluzem albo ghulią zgnilizną, może zdołam ci pomóc.', 0),
(12154, 'koKR', 'Jestem $gchory:chora;. Proszę, wylecz mnie, medyku.', 'Jestem $gchory:chora;. Proszę, wylecz mnie, medyku.', 0),
(12226, 'koKR', 'Mirando, czy możesz mi powiedzieć, ile odznak kosztują przedmioty, które oferujesz poszukiwaczom przygód z inną reputacją?', 'Mirando, czy możesz mi powiedzieć, ile odznak kosztują przedmioty, które oferujesz poszukiwaczom przygód z inną reputacją?', 0),
(12227, 'koKR', '', 'Oczywiście, $N. Powiedz mi tylko, o jaką reputację ci chodzi.\n', 0),
(12229, 'koKR', '', 'Oczywiście, $N.$B$BPoszukiwacze przygód, których Brzask uznaje za szanowanych, muszą oddać łącznie 40 odznak, by uzyskać dostęp do znakomitych przedmiotów. Za dostęp do przedmiotów jeszcze większej mocy musieliby oddać łącznie 150 odznak.$B$BMuszę przyznać, że cena jest wysoka nawet dla tych, których Brzask szanuje.\n', 0),
(12232, 'koKR', '', 'Oczywiście, $N.$B$BPoszukiwacze przygód, których Brzask czci, muszą oddać łącznie 14 odznak, by uzyskać dostęp do znakomitych przedmiotów. Za dostęp do przedmiotów jeszcze większej mocy musieliby oddać łącznie 90 odznak.$B$BCi, których Brzask czci, uznają cenę znakomitych przedmiotów za całkiem rozsądną! Koszt potężniejszych przedmiotów wciąż jest wysoki.\n', 0),
(12235, 'koKR', '', 'Oczywiście, $N.$B$BPoszukiwacze przygód, których Brzask wywyższył, muszą oddać łącznie 12 odznak, by uzyskać dostęp do znakomitych przedmiotów. Za dostęp do przedmiotów jeszcze większej mocy musieliby oddać łącznie 54 odznaki.$B$BCi, których Brzask wywyższył, dostają największe zniżki.\n', 0),
(12236, 'koKR', '', 'Oczywiście, $N.$B$BPoszukiwacze przygód, do których Brzask jest przyjaźnie nastawiony, muszą oddać łącznie 60 odznak, by uzyskać dostęp do znakomitych przedmiotów. Za dostęp do przedmiotów jeszcze większej mocy musieliby oddać łącznie 220 odznak.$B$BMuszę przyznać, że cena jest dość wysoka dla poszukiwaczy przygód, którzy nie cieszą się względami Brzasku.\n', 0),
(12237, 'koKR', 'Przyjazny.', 'Przyjazny.', 0),
(12238, 'koKR', 'Szanowany.', 'Szanowany.', 0),
(12239, 'koKR', 'Czczony.', 'Czczony.', 0),
(12240, 'koKR', 'Wywyższony.', 'Wywyższony.', 0),
(12273, 'koKR', 'Mistrz rzemiosła Omarion po prostu zniknął pewnej nocy. Jak bąk na wietrze... Puff! Nie ma go! Ech, teraz tylko ja zostałem, żeby wytwarzać towar dla chłopaków na froncie.', '', 0),
(12274, 'koKR', 'Pokaż mi swoje towary, Wilhelmie.', 'Pokaż mi swoje towary, Wilhelmie.', 0),
(50905, 'koKR', 'Przez tę mgłę nie widzę za dobrze, ale ten smród poznałbym wszędzie! Giń, plugawy ogrze!', '', 0),
(50906, 'koKR', 'Uuuuuuuuch...', '', 0),
(50907, 'koKR', 'Stary Duggan na Plagowiska szedł, by Plagę z powrotem w ziemię wbić,', '', 0),
(50908, 'koKR', 'Gdzie wiatr śmiercią cuchnie, a wszystko bure – aż się nie chce żyć.', '', 0),
(50909, 'koKR', 'A kiedy tam dotarł, cóż ujrzał krasnoludzki wzrok?', '', 0),
(50910, 'koKR', 'Sto skrzyń jęczmienia – miodu starczyłoby na rok!', '', 0),
(50911, 'koKR', 'Lecz miód ów zarazą śmierci przeklęty był, a stary Duggan też,', '', 0),
(50912, 'koKR', 'A wokół bestie Króla Lisza – cóż Duggan począć ma, no wiesz?', '', 0),
(50913, 'koKR', 'Choć czuję w sobie zarazę, ducha nie tracę wcale,', '', 0),
(50914, 'koKR', 'Jak mam i tak być Plagą, to wolę być pijany doskonale!', '', 0);
